// Dust - disk usage analyzer
// Implementation without external dependencies

use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

mod args;
mod config;
mod display;
mod node;
mod platform;
mod filter;

use args::Args;
use config::Config;
use node::Node;

fn main() {
    let mut args = Args::parse();

    // Load config file
    let config = if let Some(ref cfg_path) = args.config_file {
        Config::load_from_path(cfg_path)
    } else {
        Config::load_default()
    };

    // Apply config defaults (args take priority)
    args.apply_config(&config);

    // Get paths to analyze
    let paths = get_input_paths(&args);

    if paths.is_empty() {
        eprintln!("No valid paths specified");
        std::process::exit(1);
    }

    // Get terminal width
    let terminal_width = args.terminal_width.unwrap_or_else(|| {
        platform::get_terminal_width().unwrap_or(80)
    });

    // Show progress (unless disabled)
    let show_progress = !args.no_progress && atty_stderr();

    // Build the node tree
    let nodes = build_nodes(&paths, &args, show_progress);

    if nodes.is_empty() {
        return;
    }

    // Output results
    if args.output_json {
        output_json(&nodes, &args);
    } else {
        display::print_tree(&nodes, &args, terminal_width);
    }
}

fn atty_stderr() -> bool {
    unsafe {
        libc_isatty(2) != 0
    }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

fn libc_isatty(fd: i32) -> i32 {
    unsafe { isatty(fd) }
}

fn get_input_paths(args: &Args) -> Vec<PathBuf> {
    let mut paths = Vec::new();

    // Handle --files-from
    if let Some(ref files_from) = args.files_from {
        let content = if files_from == "-" {
            let mut s = String::new();
            use std::io::Read;
            io::stdin().read_to_string(&mut s).ok();
            s
        } else {
            fs::read_to_string(files_from).unwrap_or_default()
        };
        for line in content.lines() {
            let p = line.trim();
            if !p.is_empty() {
                paths.push(PathBuf::from(p));
            }
        }
    }

    // Handle --files0-from
    if let Some(ref files0_from) = args.files0_from {
        let content = if files0_from == "-" {
            let mut bytes = Vec::new();
            use std::io::Read;
            io::stdin().read_to_end(&mut bytes).ok();
            bytes
        } else {
            fs::read(files0_from).unwrap_or_default()
        };
        for p in content.split(|&b| b == 0) {
            if !p.is_empty() {
                if let Ok(s) = std::str::from_utf8(p) {
                    paths.push(PathBuf::from(s));
                }
            }
        }
    }

    // Add command-line paths
    for p in &args.paths {
        paths.push(PathBuf::from(p));
    }

    // Default to current directory
    if paths.is_empty() {
        paths.push(PathBuf::from("."));
    }

    // Verify paths exist
    paths.into_iter().filter(|p| {
        if p.exists() {
            true
        } else {
            eprintln!("dust: {}: No such file or directory", p.display());
            false
        }
    }).collect()
}

fn build_nodes(paths: &[PathBuf], args: &Args, show_progress: bool) -> Vec<Node> {
    if show_progress {
        eprint!("\x1b[?25l"); // Hide cursor
    }

    let mut nodes: Vec<Node> = paths.iter().map(|p| {
        scan_path(p, args, show_progress, 0)
    }).collect();

    if show_progress {
        // Clear progress line
        eprint!("\r{}\r", " ".repeat(40));
        eprint!("\x1b[?25h"); // Show cursor
        io::stderr().flush().ok();
    }

    // If multiple paths, wrap in a virtual root
    nodes
}

static PROGRESS_COUNT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
static PROGRESS_SIZE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

fn scan_path(path: &Path, args: &Args, show_progress: bool, depth: usize) -> Node {
    let meta = if args.dereference_links {
        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    };

    let meta = match meta {
        Ok(m) => m,
        Err(e) => {
            if args.print_errors {
                eprintln!("dust: {}: {}", path.display(), e);
            }
            return Node::empty(path.to_path_buf());
        }
    };

    let is_dir = if args.dereference_links {
        meta.is_dir()
    } else {
        meta.is_dir() && !meta.file_type().is_symlink()
    };

    // Check filesystem limitation
    if args.limit_filesystem {
        // TODO: implement filesystem check
    }

    // Calculate size
    let size = if args.filecount {
        if is_dir { 0 } else { 1 }
    } else if args.filetime.is_some() {
        0 // will be calculated later
    } else if args.apparent_size {
        meta.len()
    } else {
        // Use block size (512-byte blocks on Linux)
        meta.blocks() * 512
    };

    if show_progress {
        let count = PROGRESS_COUNT.fetch_add(1, std::sync::atomic::Ordering::Relaxed) + 1;
        let total_size = PROGRESS_SIZE.fetch_add(size, std::sync::atomic::Ordering::Relaxed) + size;
        if count % 100 == 0 {
            let size_str = format_size_si(total_size);
            eprint!("\r\x1b[K{} files, {}", count, size_str);
            io::stderr().flush().ok();
        }
    }

    if !is_dir || (args.dereference_links && meta.file_type().is_symlink()) {
        return Node::new(path.to_path_buf(), size, Vec::new(), meta);
    }

    // Check depth limit
    if let Some(max_depth) = args.depth {
        if depth >= max_depth {
            return Node::new(path.to_path_buf(), size, Vec::new(), meta);
        }
    }

    // Read directory
    let entries = match fs::read_dir(path) {
        Ok(e) => e,
        Err(err) => {
            if args.print_errors {
                eprintln!("dust: {}: {}", path.display(), err);
            }
            return Node::new(path.to_path_buf(), size, Vec::new(), meta);
        }
    };

    let mut children = Vec::new();
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let child_path = entry.path();

        // Check if hidden
        if args.ignore_hidden {
            if let Some(name) = child_path.file_name() {
                if name.to_string_lossy().starts_with('.') {
                    continue;
                }
            }
        }

        // Check ignore directories
        let should_ignore = args.ignore_dirs.iter().any(|ig| {
            let ig_path = Path::new(ig);
            if ig_path.is_absolute() {
                child_path == *ig_path
            } else {
                child_path.file_name().map_or(false, |n| n == std::ffi::OsStr::new(ig))
                    || child_path.ends_with(ig_path)
            }
        });

        if should_ignore {
            continue;
        }

        children.push(scan_path(&child_path, args, show_progress, depth + 1));
    }

    // Calculate directory size as sum of children
    let total_size = if args.filecount {
        children.iter().map(|c| c.size).sum::<u64>()
    } else if args.filetime.is_some() {
        children.iter().map(|c| c.size).max().unwrap_or(0)
    } else {
        size + children.iter().map(|c| c.size).sum::<u64>()
    };

    Node::new(path.to_path_buf(), total_size, children, meta)
}

fn format_size_si(bytes: u64) -> String {
    const UNITS: &[&str] = &["B", "K", "M", "G", "T"];
    const BASE: u64 = 1000;

    if bytes < BASE {
        return format!("{}B", bytes);
    }

    let mut size = bytes as f64;
    let mut unit_idx = 0;

    while size >= BASE as f64 && unit_idx < UNITS.len() - 1 {
        size /= BASE as f64;
        unit_idx += 1;
    }

    format!("{:.1}{}", size, UNITS[unit_idx])
}

fn output_json(nodes: &[Node], args: &Args) {
    if nodes.len() == 1 {
        let json = node_to_json(&nodes[0], args);
        println!("{}", json);
    } else {
        // Multiple roots - output as array
        let parts: Vec<String> = nodes.iter().map(|n| node_to_json(n, args)).collect();
        println!("[{}]", parts.join(","));
    }
}

fn node_to_json(node: &Node, args: &Args) -> String {
    let size_str = format_display_size(node.size, args);
    let name = node.path.to_string_lossy().into_owned();
    let children_json: Vec<String> = node.children.iter()
        .map(|c| node_to_json(c, args))
        .collect();

    format!(
        "{{\"size\":\"{}\",\"name\":\"{}\",\"children\":[{}]}}",
        size_str,
        name.replace('\\', "\\\\").replace('"', "\\\""),
        children_json.join(",")
    )
}

fn format_display_size(bytes: u64, args: &Args) -> String {
    use args::OutputFormat;
    match args.output_format {
        Some(OutputFormat::Si) => format_si(bytes),
        Some(OutputFormat::B) => format!("{}B", bytes),
        Some(OutputFormat::K) => format!("{}K", bytes / 1024),
        Some(OutputFormat::M) => format!("{}M", bytes / (1024*1024)),
        Some(OutputFormat::G) => format!("{}G", bytes / (1024*1024*1024)),
        Some(OutputFormat::T) => format!("{}T", bytes / (1024*1024*1024*1024)),
        Some(OutputFormat::Kb) => format!("{}K", bytes / 1000),
        Some(OutputFormat::Mb) => format!("{}M", bytes / (1000*1000)),
        Some(OutputFormat::Gb) => format!("{}G", bytes / (1000*1000*1000)),
        Some(OutputFormat::Tb) => format!("{}T", bytes / (1000*1000*1000*1000)),
        None => format_iec(bytes),
    }
}

fn format_iec(bytes: u64) -> String {
    const BASE: u64 = 1024;
    if bytes < BASE {
        return format!("{}B", bytes);
    }
    let kb = bytes as f64 / BASE as f64;
    if kb < 1000.0 {
        return format_float_with_unit(kb, "K");
    }
    let mb = kb / BASE as f64;
    if mb < 1000.0 {
        return format_float_with_unit(mb, "M");
    }
    let gb = mb / BASE as f64;
    if gb < 1000.0 {
        return format_float_with_unit(gb, "G");
    }
    let tb = gb / BASE as f64;
    format_float_with_unit(tb, "T")
}

fn format_si(bytes: u64) -> String {
    const BASE: u64 = 1000;
    if bytes < BASE {
        return format!("{}B", bytes);
    }
    let k = bytes as f64 / BASE as f64;
    if k < 1000.0 {
        return format_float_with_unit(k, "K");
    }
    let m = k / BASE as f64;
    if m < 1000.0 {
        return format_float_with_unit(m, "M");
    }
    let g = m / BASE as f64;
    if g < 1000.0 {
        return format_float_with_unit(g, "G");
    }
    let t = g / BASE as f64;
    format_float_with_unit(t, "T")
}

fn format_float_with_unit(val: f64, unit: &str) -> String {
    if val < 10.0 {
        format!("{:.1}{}", val, unit)
    } else {
        format!("{:.0}{}", val, unit)
    }
}

pub use format_display_size as fmt_size;
pub use format_iec;
pub use format_si;
pub use format_float_with_unit;

