    pub fn apply_config(&mut self, config: &Config) {
        if let Some(v) = config.reverse {
            if !self.reverse { self.reverse = v; }
        }
        if let Some(v) = config.display_full_paths {
            if !self.full_paths { self.full_paths = v; }
        }
        if let Some(v) = config.display_apparent_size {
            if !self.apparent_size { self.apparent_size = v; }
        }
        if let Some(v) = config.no_colors {
            if !self.no_colors { self.no_colors = v; }
        }
        if let Some(v) = config.no_bars {
            if !self.no_percent_bars { self.no_percent_bars = v; }
        }
        if let Some(v) = config.skip_total {
            if !self.skip_total { self.skip_total = v; }
        }
        if let Some(v) = config.ignore_hidden {
            if !self.ignore_hidden { self.ignore_hidden = v; }
        }
        if let Some(ref v) = config.output_format {
            if self.output_format.is_none() {
                self.output_format = OutputFormat::from_str(v);
            }
        }
        if let Some(v) = config.number_of_lines {
            if self.number_of_lines.is_none() {
                self.number_of_lines = Some(v);
            }
        }
    }
}

