use std::fs::Metadata;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct Node {
    pub path: PathBuf,
    pub size: u64,
    pub children: Vec<Node>,
    pub metadata: Option<StoredMeta>,
}

#[derive(Debug, Clone)]
pub struct StoredMeta {
    pub atime: u64,   // seconds since epoch
    pub mtime: u64,
    pub ctime: u64,
    pub is_dir: bool,
    pub dev: u64,
}

impl Node {
    pub fn new(path: PathBuf, size: u64, children: Vec<Node>, meta: Metadata) -> Self {
        use std::os::unix::fs::MetadataExt;

        let stored = StoredMeta {
            atime: meta.atime() as u64,
            mtime: meta.mtime() as u64,
            ctime: meta.ctime() as u64,
            is_dir: meta.is_dir(),
            dev: meta.dev(),
        };

        Node {
            path,
            size,
            children,
            metadata: Some(stored),
        }
    }

    pub fn empty(path: PathBuf) -> Self {
        Node {
            path,
            size: 0,
            children: Vec::new(),
            metadata: None,
        }
    }

    pub fn is_dir(&self) -> bool {
        if let Some(ref m) = self.metadata {
            m.is_dir
        } else {
            self.path.is_dir()
        }
    }

    pub fn name(&self) -> &str {
        self.path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_else(|| self.path.to_str().unwrap_or(""))
    }

    pub fn display_name(&self, full_paths: bool) -> String {
        if full_paths {
            self.path.to_string_lossy().into_owned()
        } else {
            self.path.file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_else(|| self.path.to_string_lossy().into_owned())
        }
    }
}

