pub fn get_terminal_width() -> Option<usize> {
    #[cfg(unix)]
    {
        use std::os::raw::c_int;

        #[repr(C)]
        struct WinSize {
            ws_row: u16,
            ws_col: u16,
            ws_xpixel: u16,
            ws_ypixel: u16,
        }

        extern "C" {
            fn ioctl(fd: c_int, request: u64, ...) -> c_int;
        }

        const TIOCGWINSZ: u64 = 0x5413;

        unsafe {
            let mut ws = WinSize {
                ws_row: 0,
                ws_col: 0,
                ws_xpixel: 0,
                ws_ypixel: 0,
            };
            let result = ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize);
            if result == 0 && ws.ws_col > 0 {
                return Some(ws.ws_col as usize);
            }
            // Try stderr
            let result = ioctl(2, TIOCGWINSZ, &mut ws as *mut WinSize);
            if result == 0 && ws.ws_col > 0 {
                return Some(ws.ws_col as usize);
            }
        }
    }
    None
}

