    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i+1] == '-' && pat[i+2] != ']' {
            items.push(ClassItem::Range(pat[i], pat[i+2]));
            i += 3;
        } else {
            items.push(ClassItem::Char(pat[i]));
            i += 1;
        }
    }

    if i < pat.len() {
        i += 1; // skip ']'
    }

    (CharPattern::Class(items, negated), i - start)
}

