/// Simple regex matcher (subset of regex features needed by dust)
/// Supports: . * + ? [] ^ $ \. \d \w \s and basic character classes

pub struct Regex {
    pattern: String,
}

impl Regex {
    pub fn new(pattern: &str) -> Option<Self> {
        Some(Regex { pattern: pattern.to_string() })
    }

    pub fn is_match(&self, text: &str) -> bool {
        regex_match(&self.pattern, text)
    }
}

fn regex_match(pattern: &str, text: &str) -> bool {
    // Convert to NFA-style match
    let pat_chars: Vec<char> = pattern.chars().collect();
    let txt_chars: Vec<char> = text.chars().collect();

    match_pattern(&pat_chars, &txt_chars, 0, 0)
}

fn match_pattern(pat: &[char], txt: &[char], pi: usize, ti: usize) -> bool {
    if pi == pat.len() {
        return ti == txt.len();
    }

    // Handle ^ anchor
    if pi == 0 && pat.get(0) == Some(&'^') {
        return match_here(&pat[1..], txt, ti);
    }

    // Match anywhere in the string
    let mut i = ti;
    loop {
        if match_here(pat, txt, i) {
            return true;
        }
        if i >= txt.len() {
            break;
        }
        i += 1;
    }
    false
}

fn match_here(pat: &[char], txt: &[char], ti: usize) -> bool {
    if pat.is_empty() {
        return true;
    }

    // $ anchor
    if pat.len() == 1 && pat[0] == '$' {
        return ti == txt.len();
    }
    if pat.len() >= 2 && pat[0] == '$' && pat[1..].iter().all(|_| false) {
        return ti == txt.len();
    }

    // Check for quantifiers
    let (ch, ch_len) = get_char_pattern(pat, 0);

    if ch_len < pat.len() {
        let next = pat[ch_len];
        if next == '*' {
            // Zero or more
            return match_star(&ch, &pat[ch_len+1..], txt, ti);
        }
        if next == '+' {
            // One or more
            if ti < txt.len() && char_matches(&ch, txt[ti]) {
                return match_star(&ch, &pat[ch_len+1..], txt, ti + 1);
            }
            return false;
        }
        if next == '?' {
            // Zero or one
            if ti < txt.len() && char_matches(&ch, txt[ti]) {
                if match_here(&pat[ch_len+1..], txt, ti + 1) {
                    return true;
                }
            }
            return match_here(&pat[ch_len+1..], txt, ti);
        }
    }

    // Match single char
    if ti < txt.len() && char_matches(&ch, txt[ti]) {
        return match_here(&pat[ch_len..], txt, ti + 1);
    }

    false
}

fn match_star(ch: &CharPattern, rest: &[char], txt: &[char], ti: usize) -> bool {
    let mut i = ti;
    loop {
        if match_here(rest, txt, i) {
            return true;
        }
        if i >= txt.len() || !char_matches(ch, txt[i]) {
            return false;
        }
        i += 1;
    }
}

#[derive(Debug)]
enum CharPattern {
    Literal(char),
    Any,           // .
    Digit,         // \d
    Word,          // \w  
    Whitespace,    // \s
    NonDigit,      // \D
    NonWord,       // \W
    NonWhitespace, // \S
    Class(Vec<ClassItem>, bool), // [...] negated
    Escaped(char), // \. etc
}

#[derive(Debug)]
enum ClassItem {
    Char(char),
    Range(char, char),
}

fn get_char_pattern(pat: &[char], pos: usize) -> (CharPattern, usize) {
    if pos >= pat.len() {
        return (CharPattern::Literal('\0'), 1);
    }

    let c = pat[pos];
    match c {
        '.' => (CharPattern::Any, 1),
        '\\' if pos + 1 < pat.len() => {
            let next = pat[pos + 1];
            let cp = match next {
                'd' => CharPattern::Digit,
                'D' => CharPattern::NonDigit,
                'w' => CharPattern::Word,
                'W' => CharPattern::NonWord,
                's' => CharPattern::Whitespace,
                'S' => CharPattern::NonWhitespace,
                _ => CharPattern::Escaped(next),
            };
            (cp, 2)
        }
        '[' => {
            let (class, len) = parse_char_class(pat, pos);
            (class, len)
        }
        _ => (CharPattern::Literal(c), 1),
    }
}

fn parse_char_class(pat: &[char], start: usize) -> (CharPattern, usize) {
    let mut i = start + 1; // skip '['
    let negated = if i < pat.len() && pat[i] == '^' {
        i += 1;
        true
    } else {
        false
    };

    let mut items = Vec::new();
    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i+1] == '-' && pat[i+2] != ']' {
            items.push(ClassItem::Range(pat[i], pat[i+2]));
            i += 3;
        } else {
            items.push(ClassItem::Char(pat[i]));
            i += 1;
        }
    }

    if i < pat.len() {
        i += 1; // skip ']'
    }

    (CharPattern::Class(items, negated), i - start)
}

fn char_matches(pattern: &CharPattern, c: char) -> bool {
    match pattern {
        CharPattern::Literal(p) => *p == c,
        CharPattern::Any => c != '\n',
        CharPattern::Digit => c.is_ascii_digit(),
        CharPattern::NonDigit => !c.is_ascii_digit(),
        CharPattern::Word => c.is_alphanumeric() || c == '_',
        CharPattern::NonWord => !(c.is_alphanumeric() || c == '_'),
        CharPattern::Whitespace => c.is_whitespace(),
        CharPattern::NonWhitespace => !c.is_whitespace(),
        CharPattern::Escaped(e) => *e == c,
        CharPattern::Class(items, negated) => {
            let in_class = items.iter().any(|item| match item {
                ClassItem::Char(ch) => *ch == c,
                ClassItem::Range(from, to) => c >= *from && c <= *to,
            });
            if *negated { !in_class } else { in_class }
        }
    }
}

pub fn matches_any_filter(path: &str, filters: &[String]) -> bool {
    filters.iter().any(|f| {
        if let Some(re) = Regex::new(f) {
            re.is_match(path)
        } else {
            false
        }
    })
}

