fn print_file_types(nodes: &[Node], args: &Args, terminal_width: usize, use_color: bool) {
    // Group files by extension
    let mut type_sizes: HashMap<String, u64> = HashMap::new();

    for node in nodes {
        collect_file_types(node, &mut type_sizes);
    }

    let total: u64 = type_sizes.values().sum();

    // Sort by size descending
    let mut types: Vec<(String, u64)> = type_sizes.into_iter().collect();
    types.sort_by(|a, b| b.1.cmp(&a.1));

    // Create display items
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if types.is_empty() {
        return;
    }

    let size_col_width = types.iter().map(|(_, s)| format_size(*s, args).len()).max().unwrap_or(4);
    let total_size_str = format_size(total, args);
    let total_size_width = total_size_str.len().max(size_col_width);

    // Show types (reversed - smallest first like normal dust output)
    let shown_types = if args.reverse {
        types.iter().rev().collect::<Vec<_>>()
    } else {
        types.iter().rev().collect::<Vec<_>>()
    };

    for (i, (ext, size)) in shown_types.iter().enumerate() {
        let size_str = format_size(*size, args);
        writeln!(out, "{:>width$}   \u{251C}\u{2500}\u{2500} {}",
            size_str, ext, width = total_size_width).ok();
    }

    // Total row
    writeln!(out, "{} \u{250C}\u{2500}\u{2534} (total)", total_size_str).ok();
}

fn collect_file_types(node: &Node, types: &mut HashMap<String, u64>) {
    if !node.is_dir() {
        let ext = node.path.extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_else(|| "(no extension)".to_string());
        *types.entry(ext).or_insert(0) += node.size;
    }
    for child in &node.children {
        collect_file_types(child, types);
    }
}

