fn libc_isatty(fd: i32) -> i32 {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) }
}

/// Pad a string with spaces on the right to reach the target visual width
fn pad_right_to(s: &str, width: usize) -> String {
    let visual_width = visual_width(s);
    if visual_width >= width {
        s.to_string()
    } else {
        let mut result = s.to_string();
        result.push_str(&" ".repeat(width - visual_width));
        result
    }
}

fn pad_right(s: &str, width: usize) -> String {
    pad_right_to(s, width)
}

/// Calculate visual width of a string (counting Unicode chars)
fn visual_width(s: &str) -> usize {
    s.chars().count()
}

#[derive(Debug, Clone)]
pub struct DisplayItem {
    pub path_display: String,
    pub size: u64,
    pub depth: usize,
    pub is_dir: bool,
    pub is_last: bool,          // is this the last item shown at this depth
    pub ancestors_is_last: Vec<bool>, // for each ancestor depth, was it last?
    pub depth1_size: u64,
    pub depth2_size: u64,
    pub depth3_size: u64,
    pub filetime_str: Option<String>,
    pub meta_ctime: u64,
}

fn get_time_filter(args: &Args) -> Option<(i64, i64)> {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()?
        .as_secs() as i64;

    // One day in seconds
    let day_secs: i64 = 86400;

    let filter_str = args.mtime.as_ref()
        .or(args.atime.as_ref())
        .or(args.ctime.as_ref())?;

    // Parse +n, -n, or n
    if filter_str.starts_with('+') {
        let n: i64 = filter_str[1..].parse().ok()?;
        // +n => files modified more than n days ago
        // range: (-inf, curr - (n+1)*day)
        let cutoff = now - (n + 1) * day_secs;
        Some((0, cutoff))
    } else if filter_str.starts_with('-') {
        let n: i64 = filter_str[1..].parse().ok()?;
        // -n => files modified less than n days ago
        // range: (curr - n*day, +inf)
        let cutoff = now - n * day_secs;
        Some((cutoff, i64::MAX))
    } else {
        let n: i64 = filter_str.parse().ok()?;
        // n => exactly n days ago
        // range: [curr-(n+1)*day, curr-n*day)
        let start = now - (n + 1) * day_secs;
        let end = now - n * day_secs;
        Some((start, end))
    }
}

fn get_file_time(node: &Node, args: &Args) -> Option<u64> {
    let meta = node.metadata.as_ref()?;
    if args.mtime.is_some() {
        Some(meta.mtime)
    } else if args.atime.is_some() {
        Some(meta.atime)
    } else if args.ctime.is_some() {
        Some(meta.ctime)
    } else {
        None
    }
}

fn passes_time_filter(node: &Node, args: &Args, filter: &Option<(i64, i64)>) -> bool {
    if let Some((start, end)) = filter {
        if let Some(t) = get_file_time(node, args) {
            let t = t as i64;
            if *end == i64::MAX {
                return t >= *start;
            } else {
                return t >= *start && t < *end;
            }
        }
        // If no metadata, include it
        true
    } else {
        true
    }
}

fn collect_display_items(
    node: &Node,
    args: &Args,
    time_filter: &Option<(i64, i64)>,
    items: &mut Vec<DisplayItem>,
    depth: usize,
    total_size: u64,
    ancestors_is_last: &mut Vec<bool>,
) {
    // Apply filters
    let path_str = node.path.to_string_lossy();

    // Filter by regex
    if !args.filter.is_empty() {
        if !filter::matches_any_filter(&path_str, &args.filter) {
            return;
        }
    }

    // Invert filter
    if !args.invert_filter.is_empty() {
        if filter::matches_any_filter(&path_str, &args.invert_filter) {
            return;
        }
    }

    // Check ignore_all_in_file filters
    // (handled similarly to invert_filter)

    // Apply time filter
    if !passes_time_filter(node, args, time_filter) {
        if node.children.is_empty() {
            return;
        }
    }

    // Apply min size filter (only to leaf nodes or if dir has no visible children)
    let passes_min_size = if let Some(min) = args.min_size {
        node.size >= min
    } else {
        true
    };

    // Apply only_dir / only_file filter
    let passes_type_filter = if args.only_dir {
        node.is_dir()
    } else if args.only_file {
        !node.is_dir()
    } else {
        true
    };

    // Get display name
    let display_name = node.display_name(args.full_paths);

    // Get depth1, depth2, depth3 ancestor sizes
    let (d1_size, d2_size, d3_size) = get_ancestor_sizes(node, depth, total_size, ancestors_is_last);

    // Process children
    if !node.children.is_empty() {
        // Check if this node is collapsed
        let is_collapsed = args.collapse.iter().any(|c| {
            node.path.file_name()
                .map(|n| n.to_string_lossy().as_ref() == c)
                .unwrap_or(false)
        });

        if !is_collapsed {
            // Sort children by size (ascending for non-reverse, descending for reverse)
            let mut sorted_children = node.children.clone();
            sorted_children.sort_by_key(|c| c.size);

            // Apply filters to determine which children will be shown
            let mut visible_children: Vec<&Node> = sorted_children.iter()
                .filter(|c| should_show_child(c, args, time_filter))
                .collect();

            if args.reverse {
                visible_children.reverse();
            }

            let n_children = visible_children.len();

            for (i, child) in visible_children.iter().enumerate() {
                let child_is_last = if args.reverse {
                    i == n_children - 1
                } else {
                    i == n_children - 1
                };

                ancestors_is_last.push(child_is_last);
                collect_display_items(
                    child,
                    args,
                    time_filter,
                    items,
                    depth + 1,
                    total_size,
                    ancestors_is_last,
                );
                ancestors_is_last.pop();
            }
        }
    }

    // Add this node
    if !passes_min_size || !passes_type_filter {
        // Don't add this node, but may have added children
        return;
    }

    let is_last = ancestors_is_last.last().copied().unwrap_or(true);

    items.push(DisplayItem {
        path_display: display_name,
        size: node.size,
        depth,
        is_dir: node.is_dir(),
        is_last,
        ancestors_is_last: ancestors_is_last.clone(),
        depth1_size: d1_size,
        depth2_size: d2_size,
        depth3_size: d3_size,
        filetime_str: None,
        meta_ctime: 0,
    });
}

fn get_ancestor_sizes(
    node: &Node,
    depth: usize,
    total_size: u64,
    ancestors_is_last: &[bool],
) -> (u64, u64, u64) {
    // We need to know the size of ancestors at depth 1, 2, 3 from root
    // This is complex without passing the sizes down
    // For now, return the total size as d1 and node size for d2/d3
    (total_size, total_size, total_size)
}

fn should_show_child(node: &Node, args: &Args, time_filter: &Option<(i64, i64)>) -> bool {
    let path_str = node.path.to_string_lossy();

    if !args.filter.is_empty() && !filter::matches_any_filter(&path_str, &args.filter) {
        // For directories, check if any children match
        if node.is_dir() {
            return node.children.iter().any(|c| should_show_child(c, args, time_filter));
        }
        return false;
    }

    if !args.invert_filter.is_empty() && filter::matches_any_filter(&path_str, &args.invert_filter) {
        return false;
    }

    true
}

fn build_tree_prefix(item: &DisplayItem, _reversed: bool) -> String {
    let mut prefix = String::new();

    let depth = item.depth;
    let ancestors = &item.ancestors_is_last;

    if depth == 0 {
        // Root node
        if item.is_dir && item.size > 0 {
            prefix.push_str(TL);
            prefix.push_str(HORIZ);
            prefix.push_str(B_JUNC);
            prefix.push(' ');
        } else {
            prefix.push_str(TL);
            prefix.push_str(HORIZ);
            prefix.push_str(HORIZ);
            prefix.push(' ');
        }
        return prefix;
    }

    // For items at depth > 0, we have ancestor columns
    // The root (depth 0) takes up column 0
    // Each depth level takes up 2 chars for "│ " or "  "

    // Build the ancestor part (everything above the current depth)
    // ancestors[0..depth-1] represent whether each ancestor was "last"
    // (where "last" means there are no more siblings of that ancestor to show)

    for i in 0..depth.saturating_sub(1) {
        // Is ancestor at level i+1 the last of its siblings?
        let anc_is_last = ancestors.get(i).copied().unwrap_or(true);
        if anc_is_last {
            prefix.push_str("  ");
        } else {
            prefix.push_str(VERT);
            prefix.push(' ');
        }
    }

    // The current item's tree char
    let is_last = item.is_last;
    let has_children = item.is_dir; // simplified

    if is_last {
        if has_children {
            prefix.push_str(TL);
            prefix.push_str(HORIZ);
            prefix.push_str(B_JUNC);
        } else {
            prefix.push_str(TL);
            prefix.push_str(HORIZ);
            prefix.push_str(HORIZ);
        }
    } else {
        if has_children {
            prefix.push_str(T_JUNC);
            prefix.push_str(HORIZ);
            prefix.push_str(B_JUNC);
        } else {
            prefix.push_str(T_JUNC);
            prefix.push_str(HORIZ);
            prefix.push_str(HORIZ);
        }
    }
    prefix.push(' ');

    prefix
}

fn compute_prefix_len(item: &DisplayItem, _reversed: bool) -> usize {
    let tree_prefix = build_tree_prefix(item, false);
    visual_width(&tree_prefix) + visual_width(&item.path_display)
}

fn build_bar(item: &DisplayItem, total: u64, bar_width: usize) -> String {
    if total == 0 || bar_width == 0 {
        return " ".repeat(bar_width);
    }

    // Calculate blocks for each level
    let d1 = item.depth1_size;
    let d2 = item.depth2_size;
    let d3 = item.depth3_size;
    let own = item.size;

    let usable = bar_width.saturating_sub(1); // last char is space separator

    let own_blocks = (own as f64 / total as f64 * bar_width as f64).round() as usize;
    let own_blocks = own_blocks.min(usable);

    // Level 1 ancestor blocks
    let d1_blocks = if d1 < total {
        (d1 as f64 / total as f64 * bar_width as f64).round() as usize
    } else {
        usable
    };
    let d1_blocks = d1_blocks.min(usable);

    // Level 2 ancestor blocks
    let d2_blocks = if d2 < d1 {
        (d2 as f64 / total as f64 * bar_width as f64).round() as usize
    } else {
        d1_blocks
    };
    let d2_blocks = d2_blocks.min(d1_blocks);

    // Level 3 ancestor blocks
    let d3_blocks = if d3 < d2 {
        (d3 as f64 / total as f64 * bar_width as f64).round() as usize
    } else {
        d2_blocks
    };
    let d3_blocks = d3_blocks.min(d2_blocks);

    let own_fill = own_blocks;
    let dark_fill = d3_blocks.saturating_sub(own_blocks);
    let med_fill = d2_blocks.saturating_sub(d3_blocks);
    let light_fill = d1_blocks.saturating_sub(d2_blocks);
    let space_fill = bar_width.saturating_sub(own_fill + dark_fill + med_fill + light_fill);

    let mut bar = String::new();
    for _ in 0..own_fill { bar.push_str(FULL_BLOCK); }
    for _ in 0..dark_fill { bar.push_str(DARK_SHADE); }
    for _ in 0..med_fill { bar.push_str(MED_SHADE); }
    for _ in 0..light_fill { bar.push_str(LIGHT_SHADE); }
    for _ in 0..space_fill { bar.push(' '); }

    bar
}

fn build_bar_right(item: &DisplayItem, total: u64, bar_width: usize) -> String {
    build_bar(item, total, bar_width)
}

fn get_color(depth: usize) -> &'static str {
    COLORS[depth % COLORS.len()]
}

pub fn format_size(size: u64, args: &Args) -> String {
    use crate::args::OutputFormat;
    match &args.output_format {
        Some(OutputFormat::Si) => crate::format_si(size),
        Some(OutputFormat::B) => format!("{}B", size),
        Some(OutputFormat::K) => format!("{}K", size / 1024),
        Some(OutputFormat::M) => format!("{}M", size / (1024*1024)),
        Some(OutputFormat::G) => format!("{}G", size / (1024*1024*1024)),
        Some(OutputFormat::T) => format!("{}T", size / (1024_u64.pow(4))),
        Some(OutputFormat::Kb) => format!("{}K", size / 1000),
        Some(OutputFormat::Mb) => format!("{}M", size / (1000*1000)),
        Some(OutputFormat::Gb) => format!("{}G", size / (1000*1000*1000)),
        Some(OutputFormat::Tb) => format!("{}T", size / (1000_u64.pow(4))),
        None => {
            if args.filecount {
                format!("{}", size)
            } else {
                crate::format_iec(size)
            }
        }
    }
}

fn print_screen_reader(items: &[DisplayItem], args: &Args, size_col_width: usize, use_color: bool) {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // Find max name width for padding
    let max_name_width = items.iter().map(|item| {
        visual_width(&item.path_display)
    }).max().unwrap_or(20);

    for item in items {
        let size_str = format_size(item.size, args);
        let name = &item.path_display;
        let depth = item.depth;
        let pct = 0u64; // TODO: calculate percentage

        // Screen reader format: name depth size pct%
        let name_padded = pad_right_to(name, max_name_width);
        let line = format!("{} {} {:>width$} {:>3}%",
            name_padded, depth, size_str, pct,
            width = size_col_width
        );
        writeln!(out, "{}", line).ok();
    }
}

fn print_file_types(nodes: &[Node], args: &Args, terminal_width: usize, use_color: bool) {
    // Group files by extension
    let mut type_sizes: HashMap<String, u64> = HashMap::new();

    for node in nodes {
        collect_file_types(node, &mut type_sizes);
    }

    let total: u64 = type_sizes.values().sum();

    // Sort by size descending
    let mut types: Vec<(String, u64)> = type_sizes.into_iter().collect();
    types.sort_by(|a, b| b.1.cmp(&a.1));

    // Create display items
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if types.is_empty() {
        return;
    }

    let size_col_width = types.iter().map(|(_, s)| format_size(*s, args).len()).max().unwrap_or(4);
    let total_size_str = format_size(total, args);
    let total_size_width = total_size_str.len().max(size_col_width);

    // Show types (reversed - smallest first like normal dust output)
    let shown_types = if args.reverse {
        types.iter().rev().collect::<Vec<_>>()
    } else {
        types.iter().rev().collect::<Vec<_>>()
    };

    for (i, (ext, size)) in shown_types.iter().enumerate() {
        let size_str = format_size(*size, args);
        writeln!(out, "{:>width$}   \u{251C}\u{2500}\u{2500} {}",
            size_str, ext, width = total_size_width).ok();
    }

    // Total row
    writeln!(out, "{} \u{250C}\u{2500}\u{2534} (total)", total_size_str).ok();
}

fn collect_file_types(node: &Node, types: &mut HashMap<String, u64>) {
    if !node.is_dir() {
        let ext = node.path.extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_else(|| "(no extension)".to_string());
        *types.entry(ext).or_insert(0) += node.size;
    }
    for child in &node.children {
        collect_file_types(child, types);
    }
}

fn print_filetime_tree(items: &[DisplayItem], args: &Args, use_color: bool) {
    // TODO: implement filetime display
}

