    if let Some(ref f) = args.files0_from {
        let content = if f == "-" {
            let mut bytes = Vec::new();
            io::stdin().read_to_end(&mut bytes).unwrap_or(0);
            bytes
        } else {
            std::fs::read(f).unwrap_or_default()
        };
        for chunk in content.split(|&b| b == 0) {
            if !chunk.is_empty() {
                if let Ok(s) = std::str::from_utf8(chunk) {
                    paths.push(PathBuf::from(s));
                }
            }
        }
    }

    for p in &args.paths {
        paths.push(PathBuf::from(p));
    }

    if paths.is_empty() {
        paths.push(PathBuf::from("."));
    }

    let mut valid = Vec::new();
    for p in paths {
        if p.exists() || p.symlink_metadata().is_ok() {
            valid.push(p);
        } else {
            eprintln!("dust: {}: No such file or directory", p.display());
        }
    }
    valid
}

