impl Args {
    pub fn parse(input: &[String]) -> Self {
        // Check for help/version first
        for arg in input.iter() {
            match arg.as_str() {
                "--version" | "-V" => { println!("Dust 1.2.3"); std::process::exit(0); }
                "--help" => { print_help(true); std::process::exit(0); }
                "-h" => { print_help(false); std::process::exit(0); }
                _ => {}
            }
        }

        let mut a = Args::default();
        let mut i = 0;

        while i < input.len() {
            let arg = &input[i];

            // Handle --key=value form
            if arg.starts_with("--") {
                if let Some(eq) = arg.find('=') {
                    let key = &arg[..eq];
                    let val = arg[eq+1..].to_string();
                    match key {
                        "--depth" => a.depth = val.parse().ok(),
                        "--threads" => a.threads = val.parse().ok(),
                        "--config" => a.config_file = Some(val),
                        "--number-of-lines" => a.number_of_lines = val.parse().ok(),
                        "--ignore-directory" => a.ignore_dirs.push(val),
                        "--ignore-all-in-file" => a.ignore_all_in_file = Some(val),
                        "--min-size" => a.min_size = parse_size(&val),
                        "--invert-filter" => a.invert_filter.push(val),
                        "--filter" => a.filter.push(val),
                        "--terminal-width" => a.terminal_width = val.parse().ok(),
                        "--output-format" => a.output_format = OutputFormat::from_str(&val),
                        "--stack-size" => a.stack_size = val.parse().ok(),
                        "--mtime" => a.mtime = Some(val),
                        "--atime" => a.atime = Some(val),
                        "--ctime" => a.ctime = Some(val),
                        "--files0-from" => a.files0_from = Some(val),
                        "--files-from" => a.files_from = Some(val),
                        "--collapse" => a.collapse.push(val),
                        "--filetime" => a.filetime = FileTime::from_str(&val),
                        _ => {}
                    }
                    i += 1;
                    continue;
                }
            }

            match arg.as_str() {
                "-d" | "--depth" => { i += 1; if i < input.len() { a.depth = input[i].parse().ok(); } }
                "-T" | "--threads" => { i += 1; if i < input.len() { a.threads = input[i].parse().ok(); } }
                "--config" => { i += 1; if i < input.len() { a.config_file = Some(input[i].clone()); } }
                "-n" | "--number-of-lines" => { i += 1; if i < input.len() { a.number_of_lines = input[i].parse().ok(); } }
                "-p" | "--full-paths" => a.full_paths = true,
                "-X" | "--ignore-directory" => { i += 1; if i < input.len() { a.ignore_dirs.push(input[i].clone()); } }
                "-I" | "--ignore-all-in-file" => { i += 1; if i < input.len() { a.ignore_all_in_file = Some(input[i].clone()); } }
                "-L" | "--dereference-links" => a.dereference_links = true,
                "-x" | "--limit-filesystem" => a.limit_filesystem = true,
                "-s" | "--apparent-size" => a.apparent_size = true,
                "-r" | "--reverse" => a.reverse = true,
                "-c" | "--no-colors" => a.no_colors = true,
                "-C" | "--force-colors" => a.force_colors = true,
                "-b" | "--no-percent-bars" => a.no_percent_bars = true,
                "-B" | "--bars-on-right" => a.bars_on_right = true,
                "-z" | "--min-size" => { i += 1; if i < input.len() { a.min_size = parse_size(&input[i]); } }
                "-R" | "--screen-reader" => a.screen_reader = true,
                "--skip-total" => a.skip_total = true,
                "-f" | "--filecount" => a.filecount = true,
                "-i" | "--ignore-hidden" => a.ignore_hidden = true,
                "-v" | "--invert-filter" => { i += 1; if i < input.len() { a.invert_filter.push(input[i].clone()); } }
                "-e" | "--filter" => { i += 1; if i < input.len() { a.filter.push(input[i].clone()); } }
                "-t" | "--file-types" => a.file_types = true,
                "-w" | "--terminal-width" => { i += 1; if i < input.len() { a.terminal_width = input[i].parse().ok(); } }
                "-P" | "--no-progress" => a.no_progress = true,
                "--print-errors" => a.print_errors = true,
                "-D" | "--only-dir" => a.only_dir = true,
                "-F" | "--only-file" => a.only_file = true,
                "-o" | "--output-format" => { 
                    i += 1; 
                    if i < input.len() { 
                        a.output_format = OutputFormat::from_str(&input[i]);
                        if a.output_format.is_none() {
                            eprintln!("error: invalid value '{}' for '--output-format <FORMAT>'", input[i]);
                            std::process::exit(1);
                        }
                    }
                }
                "-S" | "--stack-size" => { i += 1; if i < input.len() { a.stack_size = input[i].parse().ok(); } }
                "-j" | "--output-json" => a.output_json = true,
                "-M" | "--mtime" => { i += 1; if i < input.len() { a.mtime = Some(input[i].clone()); } }
                "-A" | "--atime" => { i += 1; if i < input.len() { a.atime = Some(input[i].clone()); } }
                "-y" | "--ctime" => { i += 1; if i < input.len() { a.ctime = Some(input[i].clone()); } }
                "--files0-from" => { i += 1; if i < input.len() { a.files0_from = Some(input[i].clone()); } }
                "--files-from" => { i += 1; if i < input.len() { a.files_from = Some(input[i].clone()); } }
                "--collapse" => { i += 1; if i < input.len() { a.collapse.push(input[i].clone()); } }
                "-m" | "--filetime" => { i += 1; if i < input.len() { a.filetime = FileTime::from_str(&input[i]); } }
                arg if arg.starts_with('-') && arg.len() > 1 && !arg.starts_with("--") => {
                    // Combined short flags
                    let mut j = 1;
                    let chars: Vec<char> = arg.chars().collect();
                    while j < chars.len() {
                        match chars[j] {
                            'p' => a.full_paths = true,
                            'L' => a.dereference_links = true,
                            'x' => a.limit_filesystem = true,
                            's' => a.apparent_size = true,
                            'r' => a.reverse = true,
                            'c' => a.no_colors = true,
                            'C' => a.force_colors = true,
                            'b' => a.no_percent_bars = true,
                            'B' => a.bars_on_right = true,
                            'R' => a.screen_reader = true,
                            'f' => a.filecount = true,
                            'i' => a.ignore_hidden = true,
                            't' => a.file_types = true,
                            'P' => a.no_progress = true,
                            'D' => a.only_dir = true,
                            'F' => a.only_file = true,
                            'j' => a.output_json = true,
                            'd' => { i += 1; if i < input.len() { a.depth = input[i].parse().ok(); } }
                            'n' => { i += 1; if i < input.len() { a.number_of_lines = input[i].parse().ok(); } }
                            'T' => { i += 1; if i < input.len() { a.threads = input[i].parse().ok(); } }
                            'X' => { i += 1; if i < input.len() { a.ignore_dirs.push(input[i].clone()); } }
                            'I' => { i += 1; if i < input.len() { a.ignore_all_in_file = Some(input[i].clone()); } }
                            'z' => { i += 1; if i < input.len() { a.min_size = parse_size(&input[i]); } }
                            'v' => { i += 1; if i < input.len() { a.invert_filter.push(input[i].clone()); } }
                            'e' => { i += 1; if i < input.len() { a.filter.push(input[i].clone()); } }
                            'w' => { i += 1; if i < input.len() { a.terminal_width = input[i].parse().ok(); } }
                            'o' => { 
                                i += 1; 
                                if i < input.len() { 
                                    a.output_format = OutputFormat::from_str(&input[i]);
                                }
                            }
                            'S' => { i += 1; if i < input.len() { a.stack_size = input[i].parse().ok(); } }
                            'M' => { i += 1; if i < input.len() { a.mtime = Some(input[i].clone()); } }
                            'A' => { i += 1; if i < input.len() { a.atime = Some(input[i].clone()); } }
                            'y' => { i += 1; if i < input.len() { a.ctime = Some(input[i].clone()); } }
                            'm' => { i += 1; if i < input.len() { a.filetime = FileTime::from_str(&input[i]); } }
                            _ => {}
                        }
                        j += 1;
                    }
                }
                _ => { a.paths.push(arg.clone()); }
            }
            i += 1;
        }

        // Load ignore-all-in-file
        if let Some(ref file) = a.ignore_all_in_file.clone() {
            if let Ok(content) = std::fs::read_to_string(file) {
                for line in content.lines() {
                    let l = line.trim();
                    if !l.is_empty() && !l.starts_with('#') {
                        a.extra_invert_filters.push(l.to_string());
                    }
                }
            }
        }

        a
    }

    pub fn apply_config(&mut self, config: &Config) {
        macro_rules! apply {
            ($field:ident, $cfg_field:ident) => {
                if let Some(v) = config.$cfg_field {
                    if !self.$field { self.$field = v; }
                }
            };
        }
        apply!(reverse, reverse);
        apply!(full_paths, display_full_paths);
        apply!(apparent_size, display_apparent_size);
        apply!(no_colors, no_colors);
        apply!(no_percent_bars, no_bars);
        apply!(skip_total, skip_total);
        apply!(ignore_hidden, ignore_hidden);
        if self.output_format.is_none() {
            if let Some(ref fmt) = config.output_format {
                self.output_format = OutputFormat::from_str(fmt);
            }
        }
        if self.number_of_lines.is_none() {
            if let Some(n) = config.number_of_lines {
                self.number_of_lines = Some(n);
            }
        }
    }

    pub fn all_invert_filters(&self) -> Vec<&str> {
        self.invert_filter.iter().map(|s| s.as_str())
            .chain(self.extra_invert_filters.iter().map(|s| s.as_str()))
            .collect()
    }
}

pub fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }

    let num_end = s.find(|c: char| !c.is_ascii_digit() && c != '.').unwrap_or(s.len());
    if num_end == 0 { return None; }

    let num: f64 = s[..num_end].parse().ok()?;
    let unit = s[num_end..].trim().to_lowercase();

    let mult: u64 = match unit.as_str() {
        "" | "b" => 1,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024 * 1024 * 1024,
        "t" | "tb" | "tib" => 1024_u64.pow(4),
        _ => 1,
    };

    Some((num * mult as f64) as u64)
}

