    pub fn apply_config(&mut self, config: &Config) {
        macro_rules! apply {
            ($field:ident, $cfg_field:ident) => {
                if let Some(v) = config.$cfg_field {
                    if !self.$field { self.$field = v; }
                }
            };
        }
        apply!(reverse, reverse);
        apply!(full_paths, display_full_paths);
        apply!(apparent_size, display_apparent_size);
        apply!(no_colors, no_colors);
        apply!(no_percent_bars, no_bars);
        apply!(skip_total, skip_total);
        apply!(ignore_hidden, ignore_hidden);
        if self.output_format.is_none() {
            if let Some(ref fmt) = config.output_format {
                self.output_format = OutputFormat::from_str(fmt);
            }
        }
        if self.number_of_lines.is_none() {
            if let Some(n) = config.number_of_lines {
                self.number_of_lines = Some(n);
            }
        }
    }

    pub fn all_invert_filters(&self) -> Vec<&str> {
        self.invert_filter.iter().map(|s| s.as_str())
            .chain(self.extra_invert_filters.iter().map(|s| s.as_str()))
            .collect()
    }
