            "gb" => Some(OutputFormat::Gb),
            "tb" => Some(OutputFormat::Tb),
            _ => None,
        }
    }

    pub fn is_si(&self) -> bool {
        matches!(self, OutputFormat::Si | OutputFormat::Kb | OutputFormat::Mb | 
                      OutputFormat::Gb | OutputFormat::Tb)
    }
}

