                            'v' => { i += 1; if i < input.len() { a.invert_filter.push(input[i].clone()); } }
                            'e' => { i += 1; if i < input.len() { a.filter.push(input[i].clone()); } }
                            'w' => { i += 1; if i < input.len() { a.terminal_width = input[i].parse().ok(); } }
                            'o' => { 
