#[derive(Debug, Default)]
pub struct Config {
    pub reverse: Option<bool>,
    pub display_full_paths: Option<bool>,
    pub display_apparent_size: Option<bool>,
    pub no_colors: Option<bool>,
    pub no_bars: Option<bool>,
    pub skip_total: Option<bool>,
    pub ignore_hidden: Option<bool>,
    pub output_format: Option<String>,
    pub number_of_lines: Option<usize>,
}

impl Config {
    pub fn load_default() -> Self {
        let home = std::env::var("HOME").unwrap_or_default();
        let paths = [
            format!("{}/.config/dust/config.toml", home),
            format!("{}/.dust.toml", home),
        ];
        for path in &paths {
            if let Ok(content) = std::fs::read_to_string(path) {
                return Self::parse_toml(&content);
            }
        }
        Self::default()
    }

    pub fn load_from_path(path: &str) -> Self {
        std::fs::read_to_string(path)
            .map(|c| Self::parse_toml(&c))
            .unwrap_or_default()
    }

    fn parse_toml(content: &str) -> Self {
        let mut c = Self::default();
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') { continue; }
            if let Some(eq) = line.find('=') {
                let key = line[..eq].trim().to_lowercase();
                let val = line[eq+1..].trim();
                let val = strip_quotes(val);
                match key.as_str() {
                    "reverse" => c.reverse = parse_bool(val),
                    "display-full-paths" | "full-paths" => c.display_full_paths = parse_bool(val),
                    "display-apparent-size" | "apparent-size" => c.display_apparent_size = parse_bool(val),
                    "no-colors" => c.no_colors = parse_bool(val),
                    "no-bars" | "no-percent-bars" => c.no_bars = parse_bool(val),
                    "skip-total" => c.skip_total = parse_bool(val),
                    "ignore-hidden" => c.ignore_hidden = parse_bool(val),
                    "output-format" => c.output_format = Some(val.to_string()),
                    "number-of-lines" => c.number_of_lines = val.parse().ok(),
                    _ => {}
                }
            }
        }
        c
    }
}

fn strip_quotes(s: &str) -> &str {
    if (s.starts_with('"') && s.ends_with('"')) || 
       (s.starts_with('\'') && s.ends_with('\'')) {
        &s[1..s.len()-1]
    } else {
        s
    }
}

fn parse_bool(s: &str) -> Option<bool> {
    match s.to_lowercase().as_str() {
        "true" | "yes" | "1" => Some(true),
        "false" | "no" | "0" => Some(false),
        _ => None,
    }
}
