#[cfg(unix)]
fn get_winsize() -> Option<(usize, usize)> {
    use std::os::raw::c_int;

    #[repr(C)]
    struct WinSize { ws_row: u16, ws_col: u16, _px: u16, _py: u16 }

    const TIOCGWINSZ: u64 = 0x5413;

    extern "C" { fn ioctl(fd: c_int, req: u64, ...) -> c_int; }

    for fd in [1i32, 2, 0] {
        unsafe {
            let mut ws = WinSize { ws_row: 0, ws_col: 0, _px: 0, _py: 0 };
            if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == 0 
               && ws.ws_col > 0 && ws.ws_row > 0 {
                return Some((ws.ws_row as usize, ws.ws_col as usize));
            }
        }
    }
    None
}

