pub fn regex_matches(pattern: &str, text: &str) -> bool {
    simple_regex_match(pattern, text)
}

pub fn matches_any(text: &str, patterns: &[&str]) -> bool {
    patterns.iter().any(|p| regex_matches(p, text))
}

pub fn matches_any_owned(text: &str, patterns: &[String]) -> bool {
    patterns.iter().any(|p| regex_matches(p, text))
}

fn simple_regex_match(pattern: &str, text: &str) -> bool {
    if pattern.is_empty() { return true; }

    let pat: Vec<char> = pattern.chars().collect();
    let txt: Vec<char> = text.chars().collect();

    if pat.first() == Some(&'^') {
        match_here(&pat[1..], &txt, 0)
    } else {
        for start in 0..=txt.len() {
            if match_here(&pat, &txt, start) { return true; }
        }
        false
    }
}

fn match_here(pat: &[char], txt: &[char], ti: usize) -> bool {
    if pat.is_empty() { return true; }

    if pat.len() == 1 && pat[0] == '$' { return ti == txt.len(); }
    if pat.len() >= 2 && pat[0] == '$' { return ti == txt.len() && match_here(&pat[1..], txt, ti); }

    let (cp, cp_len) = get_pattern(&pat, 0);

    if cp_len < pat.len() {
        match pat[cp_len] {
            '*' => return match_star(&cp, &pat[cp_len+1..], txt, ti),
            '+' => {
                if ti < txt.len() && cp.matches(txt[ti]) {
                    return match_star(&cp, &pat[cp_len+1..], txt, ti+1);
                }
                return false;
            }
            '?' => {
                if ti < txt.len() && cp.matches(txt[ti]) {
                    if match_here(&pat[cp_len+1..], txt, ti+1) { return true; }
                }
                return match_here(&pat[cp_len+1..], txt, ti);
            }
            _ => {}
        }
    }

    if ti < txt.len() && cp.matches(txt[ti]) {
        match_here(&pat[cp_len..], txt, ti+1)
    } else {
        false
    }
}

fn match_star(cp: &CharPat, rest: &[char], txt: &[char], mut ti: usize) -> bool {
    loop {
        if match_here(rest, txt, ti) { return true; }
        if ti >= txt.len() || !cp.matches(txt[ti]) { return false; }
        ti += 1;
    }
}

#[derive(Debug)]
enum CharPat {
    Any,
    Literal(char),
    Escaped(char),
    Digit, NonDigit,
    Word, NonWord,
    Space, NonSpace,
    Class(Vec<(char,Option<char>)>, bool), // items, negated
}

impl CharPat {
    fn matches(&self, c: char) -> bool {
        match self {
            CharPat::Any => c != '\n',
            CharPat::Literal(p) => *p == c,
            CharPat::Escaped(e) => *e == c,
            CharPat::Digit => c.is_ascii_digit(),
            CharPat::NonDigit => !c.is_ascii_digit(),
            CharPat::Word => c.is_alphanumeric() || c == '_',
            CharPat::NonWord => !(c.is_alphanumeric() || c == '_'),
            CharPat::Space => c.is_whitespace(),
            CharPat::NonSpace => !c.is_whitespace(),
            CharPat::Class(items, neg) => {
                let found = items.iter().any(|(from, to)| {
                    if let Some(t) = to { c >= *from && c <= *t }
                    else { c == *from }
                });
                if *neg { !found } else { found }
            }
        }
    }
}

fn get_pattern(pat: &[char], pos: usize) -> (CharPat, usize) {
    if pos >= pat.len() { return (CharPat::Literal('\0'), 1); }
    match pat[pos] {
        '.' => (CharPat::Any, 1),
        '\\' if pos+1 < pat.len() => {
            let cp = match pat[pos+1] {
                'd' => CharPat::Digit, 'D' => CharPat::NonDigit,
                'w' => CharPat::Word,  'W' => CharPat::NonWord,
                's' => CharPat::Space, 'S' => CharPat::NonSpace,
                c => CharPat::Escaped(c),
            };
            (cp, 2)
        }
        '[' => {
            let mut i = pos+1;
            let neg = i < pat.len() && pat[i] == '^';
            if neg { i += 1; }
            let mut items = Vec::new();
            while i < pat.len() && pat[i] != ']' {
                let from = pat[i];
                if i+2 < pat.len() && pat[i+1] == '-' && pat[i+2] != ']' {
                    items.push((from, Some(pat[i+2])));
                    i += 3;
                } else {
                    items.push((from, None));
                    i += 1;
                }
            }
            if i < pat.len() { i += 1; }
            (CharPat::Class(items, neg), i-pos)
        }
        c => (CharPat::Literal(c), 1),
    }
}

