use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::io::Write;

use crate::args::Args;
use crate::node::Node;
use crate::filter;

static FILE_COUNT: AtomicU64 = AtomicU64::new(0);
static TOTAL_SIZE: AtomicU64 = AtomicU64::new(0);

pub fn scan_paths(paths: &[PathBuf], args: &Args, show_progress: bool) -> Vec<Node> {
    FILE_COUNT.store(0, Ordering::Relaxed);
    TOTAL_SIZE.store(0, Ordering::Relaxed);

    let root_dev = if args.limit_filesystem {
        paths.first().and_then(|p| {
            fs::metadata(p).ok().map(|m| m.dev())
        })
    } else {
        None
    };

    paths.iter().map(|p| scan_path(p, args, show_progress, 0, root_dev)).collect()
}

fn update_progress(size: u64, show_progress: bool) {
    if !show_progress { return; }

    let count = FILE_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
    let total = TOTAL_SIZE.fetch_add(size, Ordering::Relaxed) + size;

    // Use a spinner animation
    let spinner = match (count / 50) % 4 {
        0 => "-",
        1 => "\\",
        2 => "|",
        _ => "/",
    };

    if count % 50 == 0 {
        let size_str = format_iec(total);
        eprint!("\r\x1b[KIndexing:  {} files, {} ... {}", count, size_str, spinner);
        let _ = std::io::stderr().flush();
    }
}

fn scan_path(path: &Path, args: &Args, show_progress: bool, depth: usize, root_dev: Option<u64>) -> Node {
    let meta = if args.dereference_links {
        fs::metadata(path)
    } else {
        fs::symlink_metadata(path)
    };

    let meta = match meta {
        Ok(m) => m,
        Err(e) => {
            if args.print_errors {
                eprintln!("dust: {}: {}", path.display(), e);
            }
            return empty_node(path);
        }
    };

    let is_symlink = meta.file_type().is_symlink();
    let is_dir = if args.dereference_links {
        meta.is_dir()
    } else {
        meta.is_dir() && !is_symlink
    };

    // Check filesystem limit
    if let Some(dev) = root_dev {
        if meta.dev() != dev {
            return empty_node(path);
        }
    }

    let own_size = if args.apparent_size {
        meta.len()
    } else {
        // disk blocks * 512
        meta.blocks() * 512
    };

    if !is_dir {
        let size = if args.filecount { 1 } else { own_size };
        update_progress(size, show_progress);
        return Node {
            path: path.to_path_buf(),
            size,
            children: Vec::new(),
            atime: meta.atime() as u64,
            mtime: meta.mtime() as u64,
            ctime: meta.ctime() as u64,
            dev: meta.dev(),
            is_dir: false,
        };
    }

    // Check depth limit
    if let Some(max_depth) = args.depth {
        if depth >= max_depth {
            let size = if args.filecount { 0 } else { own_size };
            return Node {
                path: path.to_path_buf(),
                size,
                children: Vec::new(),
                atime: meta.atime() as u64,
                mtime: meta.mtime() as u64,
                ctime: meta.ctime() as u64,
                dev: meta.dev(),
                is_dir: true,
            };
        }
    }

    // Read directory
    let entries = match fs::read_dir(path) {
        Ok(e) => e,
        Err(err) => {
            if args.print_errors {
                eprintln!("dust: {}: {}", path.display(), err);
            }
            let size = if args.filecount { 0 } else { own_size };
            return Node {
                path: path.to_path_buf(),
                size,
                children: Vec::new(),
                atime: meta.atime() as u64,
                mtime: meta.mtime() as u64,
                ctime: meta.ctime() as u64,
                dev: meta.dev(),
                is_dir: true,
            };
        }
    };

    let mut children = Vec::new();
    for entry in entries.flatten() {
        let child_path = entry.path();

        // Check hidden files
        if args.ignore_hidden {
            if let Some(name) = child_path.file_name() {
                if name.to_string_lossy().starts_with('.') {
                    continue;
                }
            }
        }

        // Check ignore dirs
        let should_ignore = args.ignore_dirs.iter().any(|ig| {
            let ig_path = Path::new(ig);
            if ig_path.is_absolute() {
                child_path == ig_path
            } else {
                child_path.file_name()
                    .map(|n| n.to_string_lossy().as_ref() == ig)
                    .unwrap_or(false)
                    || child_path.ends_with(ig_path)
            }
        });
        if should_ignore { continue; }

        children.push(scan_path(&child_path, args, show_progress, depth + 1, root_dev));
    }

    let dir_size = if args.filecount {
        children.iter().map(|c| c.size).sum::<u64>()
    } else {
        let children_total: u64 = children.iter().map(|c| c.size).sum();
        own_size + children_total
    };

    // For filetime mode, use max child time
    let atime = children.iter().map(|c| c.atime).max()
        .map(|t| t.max(meta.atime() as u64))
        .unwrap_or(meta.atime() as u64);
    let mtime = children.iter().map(|c| c.mtime).max()
        .map(|t| t.max(meta.mtime() as u64))
        .unwrap_or(meta.mtime() as u64);
    let ctime = children.iter().map(|c| c.ctime).max()
        .map(|t| t.max(meta.ctime() as u64))
        .unwrap_or(meta.ctime() as u64);

    update_progress(dir_size, show_progress);

    Node {
        path: path.to_path_buf(),
        size: dir_size,
        children,
        atime,
        mtime,
        ctime,
        dev: meta.dev(),
        is_dir: true,
    }
}

fn empty_node(path: &Path) -> Node {
    Node {
        path: path.to_path_buf(),
        size: 0,
        children: Vec::new(),
        atime: 0, mtime: 0, ctime: 0, dev: 0,
        is_dir: false,
    }
}

pub fn format_iec(bytes: u64) -> String {
    const K: u64 = 1024;
    if bytes < K { return format!("{}B", bytes); }
    let kb = bytes as f64 / K as f64;
    if kb < 1000.0 { return fmt_float(kb, "K"); }
    let mb = kb / K as f64;
    if mb < 1000.0 { return fmt_float(mb, "M"); }
    let gb = mb / K as f64;
    if gb < 1000.0 { return fmt_float(gb, "G"); }
    fmt_float(gb / K as f64, "T")
}

fn fmt_float(val: f64, unit: &str) -> String {
    if val < 10.0 { format!("{:.1}{}", val, unit) }
    else { format!("{:.0}{}", val, unit) }
}

