pub fn format_size(size: u64, args: &Args) -> String {
    match &args.output_format {
        Some(OutputFormat::Si)  => fmt_si(size),
        Some(OutputFormat::B)   => format!("{}B", size),
        Some(OutputFormat::K)   => format!("{}K", size / 1024),
        Some(OutputFormat::M)   => format!("{}M", size / (1024*1024)),
        Some(OutputFormat::G)   => format!("{}G", size / (1024*1024*1024)),
        Some(OutputFormat::T)   => format!("{}T", size / 1024_u64.pow(4)),
        Some(OutputFormat::Kb)  => format!("{}K", size / 1000),
        Some(OutputFormat::Mb)  => format!("{}M", size / (1000*1000)),
        Some(OutputFormat::Gb)  => format!("{}G", size / (1000*1000*1000)),
        Some(OutputFormat::Tb)  => format!("{}T", size / 1000_u64.pow(4)),
        None => if args.filecount { format!("{}", size) } else { fmt_iec(size) },
    }
}

fn fmt_iec(b: u64) -> String {
    const K: u64 = 1024;
    if b < K { return format!("{}B", b); }
    let v = b as f64 / K as f64;
    if v < 1000.0 { return ff(v, "K"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "M"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "G"); }
    ff(v / K as f64, "T")
}

fn fmt_si(b: u64) -> String {
    const K: u64 = 1000;
    if b < K { return format!("{}B", b); }
    let v = b as f64 / K as f64;
    if v < 1000.0 { return ff(v, "K"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "M"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "G"); }
    ff(v / K as f64, "T")
}

fn ff(v: f64, u: &str) -> String {
    if v < 10.0 { format!("{:.1}{}", v, u) } else { format!("{:.0}{}", v, u) }
}

/// Display item for rendering
#[derive(Clone)]
struct Item {
    name: String,
    size: u64,
    depth: usize,       // depth from root (root = 0)
    is_dir: bool,
    // Size of ancestors at specific depths
    anc1: u64,          // depth-1 ancestor (direct child of root)
    anc2: u64,          // depth-2 ancestor
    anc3: u64,          // depth-3 ancestor  
    // Tree prefix info
    is_last_child: bool,
    has_shown_children: bool,
    // For prefix rendering: which ancestor levels have "more siblings below"
    // anc_open[i] = true means "at level i from current, there are more siblings"
    anc_open: Vec<bool>,
    // Filetime display
    ftime_secs: Option<u64>,
    // For screen reader depth
    display_depth: usize,
}

fn time_filter_check(node: &Node, args: &Args) -> bool {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);

    let day: i64 = 86400;

    let (filter_str, file_time) = if let Some(ref s) = args.mtime {
        (s.as_str(), node.mtime as i64)
    } else if let Some(ref s) = args.atime {
        (s.as_str(), node.atime as i64)
    } else if let Some(ref s) = args.ctime {
        (s.as_str(), node.ctime as i64)
    } else {
        return true;
    };

    if filter_str.starts_with('+') {
        let n: i64 = filter_str[1..].parse().unwrap_or(0);
        file_time < now - (n+1)*day
    } else if filter_str.starts_with('-') {
        let n: i64 = filter_str[1..].parse().unwrap_or(0);
        file_time > now - n*day
    } else {
        let n: i64 = filter_str.parse().unwrap_or(0);
        let start = now - (n+1)*day;
        let end = now - n*day;
        file_time >= start && file_time < end
    }
}

fn should_include_node(node: &Node, args: &Args) -> bool {
    let path_str = node.path.to_string_lossy();

    // Filter by regex
    if !args.filter.is_empty() {
        if !filter::matches_any_owned(&path_str, &args.filter) {
            if !node.is_dir { return false; }
            // For dirs, check if any children match
            return node.children.iter().any(|c| should_include_node(c, args));
        }
    }

    // Invert filter
    if !args.invert_filter.is_empty() {
        if filter::matches_any_owned(&path_str, &args.invert_filter) {
            return false;
        }
    }

    // Extra invert filters from file
    if !args.extra_invert_filters.is_empty() {
        if filter::matches_any_owned(&path_str, &args.extra_invert_filters) {
            return false;
        }
    }

    // Type filter
    if args.only_dir && !node.is_dir { return false; }
    if args.only_file && node.is_dir { return false; }

    true
}

fn collect_items(
    node: &Node,
    args: &Args,
    items: &mut Vec<Item>,
    depth: usize,
    anc1: u64,
    anc2: u64,
    anc3: u64,
    anc_open: &[bool],
    root_total: u64,
) {
    if !should_include_node(node, args) {
        return;
    }

    // Check min size for leaf nodes
    if let Some(min) = args.min_size {
        if !node.is_dir && node.size < min {
            return;
        }
    }

    // Process children first (depth-first, children shown before parent in normal mode)
    let is_collapsed = args.collapse.iter().any(|c| {
        node.path.file_name()
            .map(|n| n.to_string_lossy().as_ref() == c)
            .unwrap_or(false)
    });

    let mut shown_children_count = 0;

    if !node.children.is_empty() && !is_collapsed {
        // Filter and sort children
        let mut sorted: Vec<&Node> = node.children.iter()
            .filter(|c| {
                // Apply min size filter for dirs if they'd show nothing
                should_include_node(c, args)
            })
            .collect();

        // Apply time filter for leaves
        sorted.retain(|c| {
            if args.mtime.is_some() || args.atime.is_some() || args.ctime.is_some() {
                if !c.is_dir {
                    time_filter_check(c, args)
                } else {
                    true // dirs pass through
                }
            } else {
                true
            }
        });

        sorted.sort_by_key(|c| c.size);
        if args.reverse { sorted.reverse(); }

        // Apply min_size filter for display
        sorted.retain(|c| {
            if let Some(min) = args.min_size {
                c.size >= min
            } else {
                true
            }
        });

        // Apply only_dir/only_file at collection level
        if args.only_dir {
            sorted.retain(|c| c.is_dir);
        } else if args.only_file {
            sorted.retain(|c| !c.is_dir);
        }

        let n = sorted.len();
        shown_children_count = n;

        for (idx, child) in sorted.iter().enumerate() {
            let child_is_last = idx == n - 1;

            // Update ancestor sizes for child
            let child_anc1 = if depth == 0 { node.size } else { anc1 };
            let child_anc2 = if depth == 1 { node.size } else if depth == 0 { node.size } else { anc2 };
            let child_anc3 = if depth == 2 { node.size } else if depth <= 1 { node.size } else { anc3 };

            let mut child_anc_open = anc_open.to_vec();
            child_anc_open.push(child_is_last);

            collect_items(
                child, args, items, 
                depth + 1,
                child_anc1, child_anc2, child_anc3,
                &child_anc_open, root_total
            );
        }
    }

    // Check time filter for this node
    if args.mtime.is_some() || args.atime.is_some() || args.ctime.is_some() {
        if !node.is_dir && !time_filter_check(node, args) {
            return;
        }
    }

    // Check min size for dirs too (if dir has no visible children that pass min_size,
    // the dir's "visible" size may be 0)

    // Add this node
    let display_name = node.display_name(args.full_paths);

    // filetime
    let ftime_secs = if let Some(ref ft) = args.filetime {
        Some(match ft {
            FileTime::Accessed => node.atime,
            FileTime::Changed => node.ctime,
            FileTime::Modified => node.mtime,
        })
    } else {
        None
    };

    let is_last = anc_open.last().copied().unwrap_or(true);

    items.push(Item {
        name: display_name,
        size: node.size,
        depth,
        is_dir: node.is_dir,
        anc1,
        anc2,
        anc3,
        is_last_child: is_last,
        has_shown_children: shown_children_count > 0,
        anc_open: anc_open.to_vec(),
        ftime_secs,
        display_depth: depth,
    });
}

// Build the prefix for normal (non-reverse) mode
fn build_prefix_normal(item: &Item) -> String {
    let mut s = String::new();
    let depth = item.depth;

    if depth == 0 {
        // Root
        if item.has_shown_children {
            s.push_str("\u{250C}\u{2500}\u{2534} "); // ┌─┴ 
        } else {
            s.push_str("\u{250C}\u{2500}\u{2500} "); // ┌── 
        }
        return s;
    }

    // For depth > 0:
    // Each ancestor (from root side) contributes 2 chars: "│ " or "  "
    // The item's own connector is 3 chars + space

    // anc_open[i] = is_last of the item at level i+1 (relative to root)
    // We need to figure out which columns stay "open" (have more siblings below)

    // anc_open[0] = is_last of item at depth=1 (the direct child of root that contains us)
    // anc_open[1] = is_last of item at depth=2
    // ...
    // anc_open[depth-1] = is_last of THIS item

    // For the prefix, we look at ancestors from root outward:
    // For each ancestor level l (1-indexed from root), 
    //   if it's NOT the last child of ITS parent = "│ "
    //   if it IS the last child = "  "

    // The anc_open vec has entries:
    // anc_open[0] = is_last of depth-1 level ancestor
    // anc_open[depth-2] = is_last of depth-1 ancestor (our parent)
    // anc_open[depth-1] = is_last of THIS node

    // So for depth=1 items, anc_open has 1 element (is_last of this item)
    // For depth=2 items, anc_open has 2 elements:
    //   [0] = is_last of depth-1 ancestor (parent)
    //   [1] = is_last of THIS item

    // Building prefix for THIS item at depth D:
    // Columns 0..D-2: "│ " or "  " based on anc_open[0..D-2]
    // Then the item's own connector: ┌─┴ or ┌── or ├─┴ or ├──

    for i in 0..depth.saturating_sub(1) {
        let anc_is_last = item.anc_open.get(i).copied().unwrap_or(true);
        if anc_is_last {
            s.push_str("  ");
        } else {
            s.push('\u{2502}'); // │
            s.push(' ');
        }
    }

    // The own connector
    let is_last = item.is_last_child;
    let has_children = item.has_shown_children;

    if is_last {
        if has_children {
            s.push_str("\u{250C}\u{2500}\u{2534} "); // ┌─┴ 
        } else {
            s.push_str("\u{250C}\u{2500}\u{2500} "); // ┌── 
        }
    } else {
        if has_children {
            s.push_str("\u{251C}\u{2500}\u{2534} "); // ├─┴ 
        } else {
            s.push_str("\u{251C}\u{2500}\u{2500} "); // ├── 
        }
    }

    s
}

// Build the prefix for reverse mode
fn build_prefix_reverse(item: &Item) -> String {
    let mut s = String::new();
    let depth = item.depth;

    if depth == 0 {
        // Root
        if item.has_shown_children {
            s.push_str("\u{2514}\u{2500}\u{252C} "); // └─┬ 
        } else {
            s.push_str("\u{2514}\u{2500}\u{2500} "); // └── 
        }
        return s;
    }

    for i in 0..depth.saturating_sub(1) {
        let anc_is_last = item.anc_open.get(i).copied().unwrap_or(true);
        if anc_is_last {
            s.push_str("  ");
        } else {
            s.push('\u{2502}'); // │
            s.push(' ');
        }
    }

    let is_last = item.is_last_child;
    let has_children = item.has_shown_children;

    if is_last {
        if has_children {
            s.push_str("\u{2514}\u{2500}\u{252C} "); // └─┬ 
        } else {
            s.push_str("\u{2514}\u{2500}\u{2500} "); // └── 
        }
    } else {
        if has_children {
            s.push_str("\u{251C}\u{2500}\u{252C} "); // ├─┬ 
        } else {
            s.push_str("\u{251C}\u{2500}\u{2500} "); // ├── 
        }
    }

    s
}

fn build_prefix(item: &Item, reverse: bool) -> String {
    if reverse {
        build_prefix_reverse(item)
    } else {
        build_prefix_normal(item)
    }
}

// Length of prefix string in display columns (each char = 1 column for box-drawing)
fn prefix_display_len(prefix: &str) -> usize {
    prefix.chars().count()
}

// Build the bar content
fn build_bar(item: &Item, total: u64, bar_len: usize) -> String {
    if total == 0 || bar_len == 0 {
        return " ".repeat(bar_len);
    }

    let usable = bar_len.saturating_sub(1); // last char always space

    // Calculate blocks for each level
    let calc_blocks = |size: u64| -> usize {
        let blocks = (size as f64 / total as f64 * bar_len as f64).round() as usize;
        blocks.min(usable)
    };

    let own_b = calc_blocks(item.size);

    // Depth 1 ancestor (direct child of root containing this item)
    let d1_b = calc_blocks(item.anc1);
    let d2_b = calc_blocks(item.anc2).min(d1_b);
    let d3_b = calc_blocks(item.anc3).min(d2_b);

    // Shade bands:
    // full: own
    // dark ▓: d3 - own  
    // medium ▒: d2 - d3
    // light ░: d1 - d2
    // space: bar_len - d1

    let full = own_b;
    let dark = d3_b.saturating_sub(own_b);
    let med = d2_b.saturating_sub(d3_b);
    let light = d1_b.saturating_sub(d2_b);
    let spaces = bar_len.saturating_sub(full + dark + med + light);

    let mut bar = String::with_capacity(bar_len * 3); // 3 bytes per UTF-8 block char
    for _ in 0..full  { bar.push('\u{2588}'); } // █
    for _ in 0..dark  { bar.push('\u{2593}'); } // ▓
    for _ in 0..med   { bar.push('\u{2592}'); } // ▒
    for _ in 0..light { bar.push('\u{2591}'); } // ░
    for _ in 0..spaces { bar.push(' '); }

    bar
}

pub fn print_tree(nodes: &[Node], args: &Args, term_width: usize) {
    if nodes.is_empty() { return; }

    let use_color = if args.no_colors { false }
        else if args.force_colors { true }
        else { is_tty_stdout() };

    if args.file_types {
        print_file_types(nodes, args, term_width, use_color);
        return;
    }

    if args.filetime.is_some() {
        print_filetime(nodes, args, use_color);
        return;
    }

    let root_size: u64 = if nodes.len() == 1 { nodes[0].size } else { nodes.iter().map(|n| n.size).sum() };

    // Collect display items
    let mut items: Vec<Item> = Vec::new();

    if nodes.len() == 1 {
        let node = &nodes[0];
        collect_items(node, args, &mut items, 0, node.size, node.size, node.size, &[], root_size);
    } else {
        for node in nodes {
            collect_items(node, args, &mut items, 0, node.size, node.size, node.size, &[], root_size);
        }
        // Add total row
        if !args.skip_total {
            items.push(Item {
                name: "(total)".to_string(),
                size: root_size,
                depth: 0,
                is_dir: true,
                anc1: root_size,
                anc2: root_size,
                anc3: root_size,
                is_last_child: true,
                has_shown_children: true,
                anc_open: vec![],
                ftime_secs: None,
                display_depth: 0,
            });
        }
    }

    if items.is_empty() { return; }

    // Determine number of lines to show
    let max_lines = args.number_of_lines.unwrap_or_else(|| {
        let h = crate::platform::get_terminal_height().unwrap_or(40);
        if h > 10 { h - 10 } else { h }
    });

    // Truncate: keep the last max_lines items (root is last)
    let start = if items.len() > max_lines { items.len() - max_lines } else { 0 };
    let items = &items[start..];

    // Skip total if requested
    let items: Vec<&Item> = if args.skip_total && items.len() > 1 && !args.output_json {
        items.iter().take(items.len().saturating_sub(1)).collect()
    } else {
        items.iter().collect()
    };

    if items.is_empty() { return; }

    if args.screen_reader {
        print_screen_reader(&items, args, root_size, use_color);
        return;
    }

    // Calculate size column width
    let size_col = items.iter().map(|i| format_size(i.size, args).len()).max().unwrap_or(4);

    // Calculate name+prefix column width
    // = max(prefix_len + name_len) across all items
    let name_col = items.iter().map(|item| {
        let prefix = build_prefix(item, args.reverse);
        prefix_display_len(&prefix) + item.name.chars().count()
    }).max().unwrap_or(16);

    if args.no_percent_bars {
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        for item in &items {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let line = format!("{:>width$} {}{}", sz, prefix, item.name, width = size_col);
            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    } else {
        // With percent bars
        // Layout: [size_col] [3 spaces if bars_on_right, else nothing] [name_col] │ [bar] │ [pct]
        // Or with bars_on_right: [size_col] [3 spaces] [name_col] │ [bar] │ [pct]
        // Default: [size_col] [3 spaces] [name_col] │ [bar] │ [pct]
        // total = size_col + 3 + name_col + 1 + bar + 1 + pct_width
        // pct_width = 5 (4 chars + %)
        // bar = term_width - size_col - 3 - name_col - 1 - 1 - 5

        let pct_width = 5; // e.g. "  31%" or " 100%"
        let overhead = size_col + 3 + name_col + 1 + 1 + pct_width;
        let bar_width = term_width.saturating_sub(overhead);

        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());

        for item in &items {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let pct = if root_size > 0 { item.size * 100 / root_size } else { 0 };
            let bar = build_bar(item, root_size, bar_width);

            // Pad name part to name_col
            let name_part = format!("{}{}", prefix, item.name);
            let name_part_len = name_part.chars().count();
            let padding = if name_part_len < name_col { name_col - name_part_len } else { 0 };

            let line = if args.bars_on_right {
                format!("{:>width$}   {}{}│{}│{:>4}%",
                    sz, name_part, " ".repeat(padding),
                    bar, pct, width = size_col)
            } else {
                format!("{:>width$}   {}{}│{}│{:>4}%",
                    sz, name_part, " ".repeat(padding),
                    bar, pct, width = size_col)
            };

            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    }
}

fn print_screen_reader(items: &[&Item], args: &Args, total: u64, use_color: bool) {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let size_col = items.iter().map(|i| format_size(i.size, args).len()).max().unwrap_or(4);
    let name_col = items.iter().map(|i| i.name.chars().count()).max().unwrap_or(20);

    for item in items {
        let sz = format_size(item.size, args);
        let pct = if total > 0 { item.size * 100 / total } else { 0 };
        let depth = item.display_depth;

        let name_pad = name_col - item.name.chars().count().min(name_col);
        let line = format!("{}{} {} {:>swidth$} {:>3}%",
            item.name, " ".repeat(name_pad),
            depth, sz, pct, swidth = size_col);

        writeln!(out, "{}", line).ok();
    }
}

fn print_file_types(nodes: &[Node], args: &Args, term_width: usize, use_color: bool) {
    let mut type_sizes: HashMap<String, u64> = HashMap::new();

    for node in nodes {
        collect_extensions(node, &mut type_sizes);
    }

    let total: u64 = type_sizes.values().sum();
    let mut types: Vec<(String, u64)> = type_sizes.into_iter().collect();
    types.sort_by(|a, b| a.1.cmp(&b.1));

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let size_col = types.iter().map(|(_, s)| format_size(*s, args).len())
        .chain(std::iter::once(format_size(total, args).len()))
        .max().unwrap_or(4);

    for (ext, size) in &types {
        let sz = format_size(*size, args);
        writeln!(out, "{:>width$}   \u{251C}\u{2500}\u{2500} {}", sz, ext, width = size_col).ok();
    }

    let total_sz = format_size(total, args);
    writeln!(out, "{:>width$} \u{250C}\u{2500}\u{2534} (total)", total_sz, width = size_col).ok();
}

fn collect_extensions(node: &Node, types: &mut HashMap<String, u64>) {
    if !node.is_dir {
        let ext = std::path::Path::new(&node.path)
            .extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_else(|| "(no extension)".to_string());
        *types.entry(ext).or_insert(0) += node.size;
    }
    for child in &node.children {
        collect_extensions(child, types);
    }
}

fn print_filetime(nodes: &[Node], args: &Args, use_color: bool) {
    let ft = args.filetime.as_ref().unwrap();

    let root_size: u64 = if nodes.len() == 1 { nodes[0].size } else { nodes.iter().map(|n| n.size).sum() };

    let mut items: Vec<Item> = Vec::new();

    for node in nodes {
        collect_items_filetime(node, args, &mut items, 0, &[], ft);
    }

    // Sort by size
    // items already in order

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for item in &items {
        let ftime = item.ftime_secs.unwrap_or(0);
        let ts = format_timestamp(ftime);
        let prefix = build_prefix_filetime(item);
        let line = format!("{}   {}{}", ts, prefix, item.name);
        writeln!(out, "{}", line).ok();
    }
}

fn format_timestamp(secs: u64) -> String {
    // Format as YYYY-MM-DDTHH:MM:SS (local time approximate using UTC)
    // Simple UTC calculation
    let s = secs;
    let secs_per_day = 86400u64;
    let secs_per_hour = 3600u64;
    let secs_per_min = 60u64;

    // Days since epoch
    let days = s / secs_per_day;
    let time_of_day = s % secs_per_day;
    let h = time_of_day / secs_per_hour;
    let m = (time_of_day % secs_per_hour) / secs_per_min;
    let sec = time_of_day % secs_per_min;

    // Calculate date from days
    let (year, month, day) = days_to_date(days);

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", year, month, day, h, m, sec)
}

fn days_to_date(days: u64) -> (u64, u64, u64) {
    // Simple Gregorian calendar calculation
    let mut d = days;
    let mut year = 1970u64;

    loop {
        let days_in_year = if is_leap(year) { 366 } else { 365 };
        if d < days_in_year { break; }
        d -= days_in_year;
        year += 1;
    }

    let months = [31u64, if is_leap(year) { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut month = 1u64;
    for &days_in_month in &months {
        if d < days_in_month { break; }
        d -= days_in_month;
        month += 1;
    }

    (year, month, d + 1)
}

fn is_leap(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn collect_items_filetime(
    node: &Node,
    args: &Args,
    items: &mut Vec<Item>,
    depth: usize,
    anc_open: &[bool],
    ft: &FileTime,
) {
    if !should_include_node(node, args) { return; }

    let mut shown_children = 0;

    if !node.children.is_empty() {
        let mut sorted: Vec<&Node> = node.children.iter().collect();
        sorted.sort_by_key(|c| {
            let t = match ft {
                FileTime::Accessed => c.atime,
                FileTime::Changed => c.ctime,
                FileTime::Modified => c.mtime,
            };
            t
        });

        let n = sorted.len();
        shown_children = n;

        for (idx, child) in sorted.iter().enumerate() {
            let child_is_last = idx == n - 1;
            let mut child_open = anc_open.to_vec();
            child_open.push(child_is_last);
            collect_items_filetime(child, args, items, depth + 1, &child_open, ft);
        }
    }

    let ftime = match ft {
        FileTime::Accessed => node.atime,
        FileTime::Changed => node.ctime,
        FileTime::Modified => node.mtime,
    };

    let is_last = anc_open.last().copied().unwrap_or(true);

    items.push(Item {
        name: node.display_name(args.full_paths),
        size: node.size,
        depth,
        is_dir: node.is_dir,
        anc1: node.size, anc2: node.size, anc3: node.size,
        is_last_child: is_last,
        has_shown_children: shown_children > 0,
        anc_open: anc_open.to_vec(),
        ftime_secs: Some(ftime),
        display_depth: depth,
    });
}

fn build_prefix_filetime(item: &Item) -> String {
    build_prefix_normal(item)
}

pub fn output_json(nodes: &[Node], args: &Args) {
    let json = if nodes.len() == 1 {
        node_to_json(&nodes[0], args)
    } else {
        let parts: Vec<String> = nodes.iter().map(|n| node_to_json(n, args)).collect();
        format!("[{}]", parts.join(","))
    };
    println!("{}", json);
}

fn node_to_json(node: &Node, args: &Args) -> String {
    let sz = format_size(node.size, args);
    let name = node.path.to_string_lossy();
    let name_escaped = name.replace('\\', "\\\\").replace('"', "\\\"");
    let children: Vec<String> = node.children.iter()
        .map(|c| node_to_json(c, args))
        .collect();
    format!(
        "{{\"size\":\"{}\",\"name\":\"{}\",\"children\":[{}]}}",
        sz, name_escaped, children.join(",")
    )
}

