fn format_timestamp(secs: u64) -> String {
    // Format as YYYY-MM-DDTHH:MM:SS (local time approximate using UTC)
    // Simple UTC calculation
    let s = secs;
    let secs_per_day = 86400u64;
    let secs_per_hour = 3600u64;
    let secs_per_min = 60u64;

    // Days since epoch
    let days = s / secs_per_day;
    let time_of_day = s % secs_per_day;
    let h = time_of_day / secs_per_hour;
    let m = (time_of_day % secs_per_hour) / secs_per_min;
    let sec = time_of_day % secs_per_min;

    // Calculate date from days
    let (year, month, day) = days_to_date(days);

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", year, month, day, h, m, sec)
}

fn days_to_date(days: u64) -> (u64, u64, u64) {
    // Simple Gregorian calendar calculation
    let mut d = days;
    let mut year = 1970u64;

    loop {
        let days_in_year = if is_leap(year) { 366 } else { 365 };
        if d < days_in_year { break; }
        d -= days_in_year;
        year += 1;
    }

    let months = [31u64, if is_leap(year) { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut month = 1u64;
    for &days_in_month in &months {
        if d < days_in_month { break; }
        d -= days_in_month;
        month += 1;
    }

    (year, month, d + 1)
}

fn is_leap(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn collect_items_filetime(
    node: &Node,
    args: &Args,
    items: &mut Vec<Item>,
    depth: usize,
    anc_open: &[bool],
    ft: &FileTime,
) {
    if !should_include_node(node, args) { return; }

    let mut shown_children = 0;

    if !node.children.is_empty() {
        let mut sorted: Vec<&Node> = node.children.iter().collect();
        sorted.sort_by_key(|c| {
            let t = match ft {
                FileTime::Accessed => c.atime,
                FileTime::Changed => c.ctime,
                FileTime::Modified => c.mtime,
            };
            t
        });

        let n = sorted.len();
        shown_children = n;

        for (idx, child) in sorted.iter().enumerate() {
            let child_is_last = idx == n - 1;
            let mut child_open = anc_open.to_vec();
            child_open.push(child_is_last);
            collect_items_filetime(child, args, items, depth + 1, &child_open, ft);
        }
    }

    let ftime = match ft {
        FileTime::Accessed => node.atime,
        FileTime::Changed => node.ctime,
        FileTime::Modified => node.mtime,
    };

    let is_last = anc_open.last().copied().unwrap_or(true);

    items.push(Item {
        name: node.display_name(args.full_paths),
        size: node.size,
        depth,
        is_dir: node.is_dir,
        anc1: node.size, anc2: node.size, anc3: node.size,
        is_last_child: is_last,
        has_shown_children: shown_children > 0,
        anc_open: anc_open.to_vec(),
        ftime_secs: Some(ftime),
        display_depth: depth,
    });
}

fn build_prefix_filetime(item: &Item) -> String {
    build_prefix_normal(item)
}

