        };

        for (asc_idx, child) in display_order.iter() {
            let asc_idx = *asc_idx;
            let is_first_disp = if args.reverse { asc_idx == n-1 } else { asc_idx == 0 };
            let is_last_disp = if args.reverse { asc_idx == 0 } else { asc_idx == n-1 };

            // pipe_open for THIS ancestor level: does this item have more siblings after it?
            let pipe_open = !is_last_disp;

            // Ancestor sizes for the child
            let child_anc1 = if depth == 0 { node.size } else { anc1 };
            let child_anc2 = if depth == 1 { node.size } else if depth == 0 { node.size } else { anc2 };
            let child_anc3 = if depth == 2 { node.size } else if depth == 1 { node.size } else if depth == 0 { node.size } else { anc3 };

            let mut child_pipe = anc_pipe_open.to_vec();
            child_pipe.push(pipe_open);

            collect_items(child, args, items, depth+1, &child_pipe,
