use std::collections::HashMap;
use std::io::{self, Write};
use crate::args::{Args, FileTime, OutputFormat};
use crate::node::Node;
use crate::filter;

const RESET: &str = "\x1b[0m";
const COLORS: &[&str] = &[
    "\x1b[36m",  "\x1b[33m",  "\x1b[32m",  "\x1b[31m",
    "\x1b[35m",  "\x1b[34m",  "\x1b[93m",  "\x1b[92m",
    "\x1b[96m",  "\x1b[95m",  "\x1b[91m",  "\x1b[94m",
];

fn get_color(depth: usize) -> &'static str {
    COLORS[depth % COLORS.len()]
}

fn is_tty_stdout() -> bool {
    extern "C" { fn isatty(fd: i32) -> i32; }
    unsafe { isatty(1) != 0 }
}

pub fn format_size(size: u64, args: &Args) -> String {
    match &args.output_format {
        Some(OutputFormat::Si)  => fmt_si(size),
        Some(OutputFormat::B)   => format!("{}B", size),
        Some(OutputFormat::K)   => format!("{}K", size / 1024),
        Some(OutputFormat::M)   => format!("{}M", size / (1024*1024)),
        Some(OutputFormat::G)   => format!("{}G", size / (1024*1024*1024)),
        Some(OutputFormat::T)   => format!("{}T", size / 1024_u64.pow(4)),
        Some(OutputFormat::Kb)  => format!("{}K", size / 1000),
        Some(OutputFormat::Mb)  => format!("{}M", size / (1000*1000)),
        Some(OutputFormat::Gb)  => format!("{}G", size / (1000*1000*1000)),
        Some(OutputFormat::Tb)  => format!("{}T", size / 1000_u64.pow(4)),
        None => if args.filecount { format!("{}", size) } else { fmt_iec(size) },
    }
}

pub fn fmt_iec(b: u64) -> String {
    const K: u64 = 1024;
    if b < K { return format!("{}B", b); }
    let v = b as f64 / K as f64;
    if v < 1000.0 { return ff(v, "K"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "M"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "G"); }
    ff(v / K as f64, "T")
}

fn fmt_si(b: u64) -> String {
    const K: u64 = 1000;
    if b < K { return format!("{}B", b); }
    let v = b as f64 / K as f64;
    if v < 1000.0 { return ff(v, "K"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "M"); }
    let v = v / K as f64;
    if v < 1000.0 { return ff(v, "G"); }
    ff(v / K as f64, "T")
}

fn ff(v: f64, u: &str) -> String {
    if v < 10.0 { format!("{:.1}{}", v, u) } else { format!("{:.0}{}", v, u) }
}

#[derive(Clone)]
struct Item {
    name: String,
    size: u64,
    depth: usize,
    is_dir: bool,
    // In non-reversed mode: is_first = is SMALLEST child = ┌ connector
    // In reversed mode: is_first = is LARGEST child = shown first = NOT last = ├ connector 
    // Actually this is the "first in display order" concept
    // We use it differently: 
    // non-reversed: ┌ if first (smallest, display-idx=0), ├ otherwise
    // reversed: └ if last displayed (smallest, display-idx=n-1), ├ otherwise
    is_first_child: bool,    // ascending idx == 0 (= smallest)
    has_shown_children: bool,
    // For each ancestor depth, is the pipe open (more siblings displayed after this ancestor)?
    // non-reversed: pipe_open[k] = ancestor_at_depth_k+1 is NOT the largest (has bigger siblings after)
    // reversed: pipe_open[k] = ancestor_at_depth_k+1 is NOT the smallest (has smaller siblings after = displayed after)
    anc_pipe_open: Vec<bool>,
    anc1_size: u64,
    anc2_size: u64,
    anc3_size: u64,
    ftime_secs: Option<u64>,
}

fn should_include(node: &Node, args: &Args) -> bool {
    let path_str = node.path.to_string_lossy();

    if !args.filter.is_empty() {
        if !filter::matches_any_owned(&path_str, &args.filter) {
            if !node.is_dir { return false; }
            return node.children.iter().any(|c| should_include(c, args));
        }
    }

    if filter::matches_any_owned(&path_str, &args.invert_filter) { return false; }
    if filter::matches_any_owned(&path_str, &args.extra_invert_filters) { return false; }
    if args.only_dir && !node.is_dir { return false; }
    if args.only_file && node.is_dir { return false; }

    true
}

fn time_pass(node: &Node, args: &Args) -> bool {
    let filter_str = if let Some(ref s) = args.mtime { s }
        else if let Some(ref s) = args.atime { s }
        else if let Some(ref s) = args.ctime { s }
        else { return true; };

    let file_time = if args.mtime.is_some() { node.mtime as i64 }
        else if args.atime.is_some() { node.atime as i64 }
        else { node.ctime as i64 };

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default().as_secs() as i64;
    let day = 86400i64;

    if filter_str.starts_with('+') {
        let n: i64 = filter_str[1..].parse().unwrap_or(0);
        file_time < now - (n+1)*day
    } else if filter_str.starts_with('-') {
        let n: i64 = filter_str[1..].parse().unwrap_or(0);
        file_time > now - n*day
    } else {
        let n: i64 = filter_str.parse().unwrap_or(0);
        file_time >= now-(n+1)*day && file_time < now-n*day
    }
}

fn collect_items(
    node: &Node,
    args: &Args,
    items: &mut Vec<Item>,
    depth: usize,
    anc_pipe_open: &[bool],
    is_first_child: bool,
    anc1: u64, anc2: u64, anc3: u64,
    total_size: u64,
) {
    if !should_include(node, args) { return; }
    if let Some(min) = args.min_size { if !node.is_dir && node.size < min { return; } }

    let has_time = args.mtime.is_some() || args.atime.is_some() || args.ctime.is_some();
    if has_time && !node.is_dir && !time_pass(node, args) { return; }

    let is_collapsed = args.collapse.iter().any(|c| {
        node.path.file_name().map(|n| n.to_string_lossy().as_ref() == c).unwrap_or(false)
    });

    let mut shown_children = 0;

    if !node.children.is_empty() && !is_collapsed {
        let mut children: Vec<&Node> = node.children.iter()
            .filter(|c| {
                if !should_include(c, args) { return false; }
                if let Some(min) = args.min_size { if c.size < min { return false; } }
                if has_time && !c.is_dir && !time_pass(c, args) { return false; }
                true
            })
            .collect();

        // Sort ascending
        children.sort_by_key(|c| c.size);
        let n = children.len();

        if n > 0 {
            shown_children = n;

            // Iterate in display order
            // non-reversed: ascending (smallest first)
            // reversed: descending (largest first = n-1 down to 0)
            let display_seq: Vec<usize> = if args.reverse {
                (0..n).rev().collect()
            } else {
                (0..n).collect()
            };

            for (display_idx, &asc_idx) in display_seq.iter().enumerate() {
                let child = children[asc_idx];
                let child_is_first = asc_idx == 0; // smallest = first in ascending sort

                // is_last_displayed: the last item in the display sequence
                // non-reversed: asc_idx == n-1 (largest = last displayed = last before parent)
                // reversed: asc_idx == 0 (smallest = last displayed)
                let is_last_displayed = display_idx == n - 1;
                let pipe_open = !is_last_displayed;

                let child_anc1 = if depth == 0 { node.size } else { anc1 };
                let child_anc2 = if depth == 1 { node.size } else if depth == 0 { node.size } else { anc2 };
                let child_anc3 = if depth == 2 { node.size } else if depth <= 1 { node.size } else { anc3 };

                let mut child_pipe = anc_pipe_open.to_vec();
                child_pipe.push(pipe_open);

                collect_items(child, args, items, depth+1, &child_pipe,
                    child_is_first, child_anc1, child_anc2, child_anc3, total_size);
            }
        }
    }

    let ftime_secs = args.filetime.as_ref().map(|ft| match ft {
        FileTime::Accessed => node.atime,
        FileTime::Changed => node.ctime,
        FileTime::Modified => node.mtime,
    });

    items.push(Item {
        name: node.display_name(args.full_paths),
        size: node.size,
        depth,
        is_dir: node.is_dir,
        is_first_child,
        has_shown_children: shown_children > 0,
        anc_pipe_open: anc_pipe_open.to_vec(),
        anc1_size: anc1,
        anc2_size: anc2,
        anc3_size: anc3,
        ftime_secs,
    });
}

/// Build the tree prefix string for an item.
/// Returns the prefix string (NOT including the size or the name).
/// 
/// Format (after size column):
///   depth 0: " " + connector + " "     (1 + 3 + 1 = 5 chars, but connector is 3 chars = "┌─┴" etc.)
///   depth d>=1: "   " + [level columns] + connector + " "
///     where level columns = (d-1) * 2 chars each: "│ " or "  "
///     total = 3 + (d-1)*2 + 4 = 2*d + 5 chars
fn build_prefix(item: &Item, reverse: bool) -> String {
    let mut s = String::new();
    let d = item.depth;

    if d == 0 {
        // Root
        s.push(' ');
        push_connector(&mut s, item, reverse);
        s.push(' ');
        return s;
    }

    // Base indent: 3 spaces
    s.push_str("   ");

    // Level columns for depths 1..d-1
    // anc_pipe_open[0] = is_pipe_open for depth-1 ancestor (most ancestral)
    // anc_pipe_open[d-2] = is_pipe_open for depth d-1 ancestor (direct parent)
    // We show columns from anc_pipe_open[0] to anc_pipe_open[d-2]
    // (The last entry anc_pipe_open[d-1] if it exists is for THIS item's parent,
    //  but we use it in the connector choice... actually no)

    // anc_pipe_open has length d (one per depth level, from 1 to d)
    // anc_pipe_open[k] corresponds to the ancestor at depth k+1
    // For level columns, we use anc_pipe_open[0..d-1-1] = anc_pipe_open[0..d-2]
    for k in 0..d.saturating_sub(1) {
        let open = item.anc_pipe_open.get(k).copied().unwrap_or(false);
        if open {
            s.push('\u{2502}'); // │
            s.push(' ');
        } else {
            s.push_str("  ");
        }
    }

    push_connector(&mut s, item, reverse);
    s.push(' ');
    s
}

fn push_connector(s: &mut String, item: &Item, reverse: bool) {
    let has_children = item.has_shown_children;

    // Which starting char?
    // Non-reversed: ┌ if is_first_child (smallest, idx=0), ├ otherwise
    // Reversed: └ if is_first_child (smallest, idx=0, shown LAST), ├ otherwise
    let start_char = if reverse {
        if item.is_first_child { '\u{2514}' } else { '\u{251C}' } // └ or ├
    } else {
        if item.is_first_child { '\u{250C}' } else { '\u{251C}' } // ┌ or ├
    };

    s.push(start_char);
    s.push('\u{2500}'); // ─

    if has_children {
        // Non-reversed: ┴ (bottom T)
        // Reversed: ┬ (top T)
        if reverse {
            s.push('\u{252C}'); // ┬
        } else {
            s.push('\u{2534}'); // ┴
        }
    } else {
        s.push('\u{2500}'); // ─
    }
}

fn build_bar(item: &Item, total: u64, bar_len: usize) -> String {
    if total == 0 || bar_len == 0 { return " ".repeat(bar_len); }

    let usable = bar_len.saturating_sub(1);

    let calc = |size: u64| -> usize {
        ((size as f64 / total as f64 * bar_len as f64).round() as usize).min(usable)
    };

    let own_b = calc(item.size);
    let d1_b = calc(item.anc1_size);
    let d2_b = calc(item.anc2_size).min(d1_b);
    let d3_b = calc(item.anc3_size).min(d2_b);

    let full = own_b;
    let dark = d3_b.saturating_sub(own_b);
    let med = d2_b.saturating_sub(d3_b);
    let light = d1_b.saturating_sub(d2_b);
    let spaces = bar_len.saturating_sub(full + dark + med + light);

    let mut bar = String::new();
    for _ in 0..full  { bar.push('\u{2588}'); } // █
    for _ in 0..dark  { bar.push('\u{2593}'); } // ▓
    for _ in 0..med   { bar.push('\u{2592}'); } // ▒
    for _ in 0..light { bar.push('\u{2591}'); } // ░
    for _ in 0..spaces { bar.push(' '); }

    bar
}

pub fn print_tree(nodes: &[Node], args: &Args, term_width: usize) {
    if nodes.is_empty() { return; }

    let use_color = if args.no_colors { false }
        else if args.force_colors { true }
        else { is_tty_stdout() };

    if args.file_types {
        print_file_types(nodes, args, term_width, use_color);
        return;
    }

    if args.filetime.is_some() {
        print_filetime(nodes, args, use_color);
        return;
    }

    let root_size: u64 = if nodes.len() == 1 { nodes[0].size } 
        else { nodes.iter().map(|n| n.size).sum() };

    let mut items: Vec<Item> = Vec::new();

    if nodes.len() == 1 {
        let node = &nodes[0];
        collect_items(node, args, &mut items, 0, &[], true,
            node.size, node.size, node.size, root_size);
    } else {
        // Multiple paths: treat each as a top-level item
        let mut sorted_nodes: Vec<&Node> = nodes.iter().collect();
        sorted_nodes.sort_by_key(|n| n.size);
        let n = sorted_nodes.len();

        let display_seq: Vec<usize> = if args.reverse {
            (0..n).rev().collect()
        } else {
            (0..n).collect()
        };

        for (display_idx, &asc_idx) in display_seq.iter().enumerate() {
            let node = sorted_nodes[asc_idx];
            let is_first = asc_idx == 0;
            let pipe_open = display_idx < n - 1;
            collect_items(node, args, &mut items, 0, &[pipe_open],
                is_first, node.size, node.size, node.size, root_size);
        }

        // Total row
        if !args.skip_total {
            items.push(Item {
                name: "(total)".to_string(),
                size: root_size,
                depth: 0,
                is_dir: true,
                is_first_child: true,
                has_shown_children: true,
                anc_pipe_open: vec![],
                anc1_size: root_size,
                anc2_size: root_size,
                anc3_size: root_size,
                ftime_secs: None,
            });
        }
    }

    if items.is_empty() { return; }

    // Limit number of lines
    let max_lines = args.number_of_lines.unwrap_or_else(|| {
        let h = crate::platform::get_terminal_height().unwrap_or(40);
        if h > 10 { h - 10 } else { h }
    });

    let start = if items.len() > max_lines { items.len() - max_lines } else { 0 };
    let items = &items[start..];

    // Skip total if requested
    let items_slice: &[Item] = if args.skip_total && nodes.len() == 1 {
        if items.len() > 1 { &items[..items.len()-1] } else { items }
    } else {
        items
    };

    if items_slice.is_empty() { return; }

    if args.screen_reader {
        print_screen_reader(items_slice, args, root_size, use_color);
        return;
    }

    let size_col = items_slice.iter().map(|i| format_size(i.size, args).len()).max().unwrap_or(4);

    // Calculate name column width
    let name_col = items_slice.iter().map(|item| {
        let prefix = build_prefix(item, args.reverse);
        prefix.chars().count() + item.name.chars().count()
    }).max().unwrap_or(10);

    if args.no_percent_bars {
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        for item in items_slice {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let line = format!("{:>width$} {}{}", sz, prefix, item.name, width = size_col);
            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    } else {
        let pct_width = 5; // "  31%" or " 100%"
        let overhead = size_col + 3 + name_col + 1 + 1 + pct_width;
        let bar_width = if term_width > overhead { term_width - overhead } else { 0 };

        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());

        for item in items_slice {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let pct = if root_size > 0 { item.size * 100 / root_size } else { 0 };
            let bar = build_bar(item, root_size, bar_width);

            let name_part = format!("{}{}", prefix, item.name);
            let name_part_len = name_part.chars().count();
            let padding = if name_part_len < name_col { name_col - name_part_len } else { 0 };

            let line = format!("{:>width$}   {}{}│{}│{:>4}%",
                sz, name_part, " ".repeat(padding),
                bar, pct, width = size_col);

            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    }
}

fn print_screen_reader(items: &[Item], args: &Args, total: u64, _use_color: bool) {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let size_col = items.iter().map(|i| format_size(i.size, args).len()).max().unwrap_or(4);
    let name_col = items.iter().map(|i| i.name.chars().count()).max().unwrap_or(20);

    for item in items {
        let sz = format_size(item.size, args);
        let pct = if total > 0 { item.size * 100 / total } else { 0 };
        let depth = item.depth;
        let name_pad = name_col.saturating_sub(item.name.chars().count());
        let line = format!("{}{} {} {:>swidth$} {:>3}%",
            item.name, " ".repeat(name_pad),
            depth, sz, pct, swidth = size_col);
        writeln!(out, "{}", line).ok();
    }
}

fn print_file_types(nodes: &[Node], args: &Args, _term_width: usize, _use_color: bool) {
    let mut type_sizes: HashMap<String, u64> = HashMap::new();
    for node in nodes { collect_extensions(node, &mut type_sizes); }

    let total: u64 = type_sizes.values().sum();
    let mut types: Vec<(String, u64)> = type_sizes.into_iter().collect();
    types.sort_by_key(|(_, s)| *s);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let size_col = types.iter().map(|(_, s)| format_size(*s, args).len())
        .chain(std::iter::once(format_size(total, args).len()))
        .max().unwrap_or(4);

    for (ext, size) in &types {
        let sz = format_size(*size, args);
        writeln!(out, "{:>width$}   \u{251C}\u{2500}\u{2500} {}", sz, ext, width = size_col).ok();
    }
    let total_sz = format_size(total, args);
    writeln!(out, "{:>width$} \u{250C}\u{2500}\u{2534} (total)", total_sz, width = size_col).ok();
}

fn collect_extensions(node: &Node, types: &mut HashMap<String, u64>) {
    if !node.is_dir {
        let ext = node.path.extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_else(|| "(no extension)".to_string());
        *types.entry(ext).or_insert(0) += node.size;
    }
    for child in &node.children { collect_extensions(child, types); }
}

fn print_filetime(nodes: &[Node], args: &Args, _use_color: bool) {
    let ft = args.filetime.as_ref().unwrap();
    let root_size: u64 = nodes.iter().map(|n| n.size).sum();

    let mut items: Vec<Item> = Vec::new();
    for node in nodes {
        collect_items_ft(node, args, &mut items, 0, &[], true, ft);
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for item in &items {
        let ftime = item.ftime_secs.unwrap_or(0);
        let ts = format_timestamp(ftime);
        let prefix = build_prefix_ft(item);
        writeln!(out, "{}   {}{}", ts, prefix, item.name).ok();
    }
}

fn build_prefix_ft(item: &Item) -> String {
    let d = item.depth;
    let mut s = String::new();

    if d == 0 {
        s.push('\u{250C}'); s.push('\u{2500}'); s.push('\u{2534}'); // ┌─┴
        return s;
    }

    for k in 0..d.saturating_sub(1) {
        let open = item.anc_pipe_open.get(k).copied().unwrap_or(false);
        if open { s.push('\u{2502}'); s.push(' '); }
        else { s.push_str("  "); }
    }

    if item.is_first_child {
        s.push('\u{250C}'); // ┌
    } else {
        s.push('\u{251C}'); // ├
    }
    s.push('\u{2500}'); // ─
    if item.has_shown_children {
        s.push('\u{2534}'); // ┴
    } else {
        s.push('\u{2500}'); // ─
    }
    s
}

fn collect_items_ft(
    node: &Node,
    args: &Args,
    items: &mut Vec<Item>,
    depth: usize,
    anc_pipe_open: &[bool],
    is_first: bool,
    ft: &FileTime,
) {
    if !should_include(node, args) { return; }

    let mut shown = 0;

    if !node.children.is_empty() {
        let mut children: Vec<&Node> = node.children.iter()
            .filter(|c| should_include(c, args))
            .collect();

        // Sort by filetime
        children.sort_by_key(|c| match ft {
            FileTime::Accessed => c.atime,
            FileTime::Changed => c.ctime,
            FileTime::Modified => c.mtime,
        });

        let n = children.len();
        shown = n;

        for (asc_idx, child) in children.iter().enumerate() {
            let child_is_first = asc_idx == 0;
            let is_last_disp = asc_idx == n - 1;
            let pipe_open = !is_last_disp;

            let mut child_pipe = anc_pipe_open.to_vec();
            child_pipe.push(pipe_open);

            collect_items_ft(child, args, items, depth+1, &child_pipe, child_is_first, ft);
        }
    }

    let ftime = Some(match ft {
        FileTime::Accessed => node.atime,
        FileTime::Changed => node.ctime,
        FileTime::Modified => node.mtime,
    });

    items.push(Item {
        name: node.display_name(args.full_paths),
        size: node.size,
        depth,
        is_dir: node.is_dir,
        is_first_child: is_first,
        has_shown_children: shown > 0,
        anc_pipe_open: anc_pipe_open.to_vec(),
        anc1_size: 0, anc2_size: 0, anc3_size: 0,
        ftime_secs: ftime,
    });
}

fn format_timestamp(secs: u64) -> String {
    let day = secs / 86400;
    let tod = secs % 86400;
    let h = tod / 3600;
    let m = (tod % 3600) / 60;
    let s = tod % 60;
    let (y, mo, d) = days_to_ymd(day);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, d, h, m, s)
}

fn days_to_ymd(mut days: u64) -> (u64, u64, u64) {
    let mut y = 1970u64;
    loop {
        let diy = if is_leap(y) { 366 } else { 365 };
        if days < diy { break; }
        days -= diy;
        y += 1;
    }
    let months = [31u64, if is_leap(y) { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut mo = 1u64;
    for &dim in &months {
        if days < dim { break; }
        days -= dim;
        mo += 1;
    }
    (y, mo, days + 1)
}

fn is_leap(y: u64) -> bool { (y%4==0 && y%100!=0) || y%400==0 }

pub fn output_json(nodes: &[Node], args: &Args) {
    let json = if nodes.len() == 1 {
        node_to_json(&nodes[0], args)
    } else {
        let parts: Vec<String> = nodes.iter().map(|n| node_to_json(n, args)).collect();
        format!("[{}]", parts.join(","))
    };
    println!("{}", json);
}

fn node_to_json(node: &Node, args: &Args) -> String {
    let sz = format_size(node.size, args);
    let name = node.path.to_string_lossy();
    let name_esc = name.replace('\\', "\\\\").replace('"', "\\\"");
    let kids: Vec<String> = node.children.iter().map(|c| node_to_json(c, args)).collect();
    format!("{{\"size\":\"{}\",\"name\":\"{}\",\"children\":[{}]}}", sz, name_esc, kids.join(","))
}

