        name: node.display_name(args.full_paths),
        size: node.size,
        depth,
        is_dir: node.is_dir,
        is_first_child,
        has_shown_children: shown > 0,
        anc_pipe_open: anc_pipe_open.to_vec(),
        anc1_size: anc1,
        anc2_size: anc2,
        anc3_size: anc3,
        ftime_secs,
