        let d = items[i].depth;
        if d == 0 {
            items[i].anc_pipe_open = vec![];
            continue;
        }

        let mut new_pipe_open = vec![false; d];

        if !reversed {
            // Find ancestor at each depth k+1 by going FORWARD from position i
            for k in 0..d {
                let anc_depth = k + 1;
                // Find nearest item at depth anc_depth AFTER position i
                let mut anc_pos = None;
                for j in (i+1)..n {
                    if items[j].depth == anc_depth {
                        anc_pos = Some(j);
                        break;
                    }
                    if items[j].depth < anc_depth {
                        // We've gone past any potential ancestors at this depth
                        break;
                    }
                }

                if let Some(ap) = anc_pos {
                    // Is items[ap] the first of its siblings in the display?
                    // Scan BACKWARDS from ap: if we find item at same depth before hitting
                    // an item at depth < anc_depth, it's a sibling → NOT first
                    let mut is_first = true;
                    let mut j = if ap > 0 { ap - 1 } else { 0 };
                    if ap > 0 {
                        loop {
                            if items[j].depth < anc_depth { break; }
                            if items[j].depth == anc_depth {
                                is_first = false;
                                break;
                            }
                            if j == 0 { break; }
                            j -= 1;
                        }
                    }
                    new_pipe_open[k] = !is_first;
                } else {
                    new_pipe_open[k] = false;
                }
            }
        } else {
            // Reversed mode: parent appears BEFORE children
            // Find ancestor at depth k+1 by going BACKWARD from i
            for k in 0..d {
                let anc_depth = k + 1;
                let mut anc_pos = None;
                if i > 0 {
                    let mut j = i - 1;
                    loop {
                        if items[j].depth == anc_depth {
                            anc_pos = Some(j);
                            break;
                        }
                        if items[j].depth < anc_depth { break; }
                        if j == 0 { break; }
                        j -= 1;
                    }
                }

                if let Some(ap) = anc_pos {
                    // In reversed: is_first = is this item the LAST of its siblings?
                    // = no sibling appears AFTER it (going forward until depth < anc_depth)
                    let mut is_last = true;
                    for j in (ap+1)..n {
                        if items[j].depth < anc_depth { break; }
                        if items[j].depth == anc_depth {
                            is_last = false;
