                    // In reversed: └ = last = is_first_child = asc_idx==0 = smallest
                    // pipe_open = NOT is_last
                    new_pipe_open[k] = !is_last;
                } else {
                    new_pipe_open[k] = false;
                }
            }
        }

        items[i].anc_pipe_open = new_pipe_open;
