fn print_only_file(nodes: &[crate::node::Node], args: &Args, term_width: usize, use_color: bool) {
    // Collect all files (and empty directories) from the tree, show as flat list
    let mut all_files: Vec<&crate::node::Node> = Vec::new();
    for node in nodes {
        all_files.extend(collect_flat_files(node));
    }

    // Sort ascending by size, then path
    all_files.sort_by(|a, b| a.size.cmp(&b.size).then_with(|| a.path.cmp(&b.path)));

    let root_size: u64 = nodes.iter().map(|n| n.size).sum();
    let n = all_files.len();

    // Build flat Item list
    let mut items: Vec<Item> = Vec::new();
    for (i, file) in all_files.iter().enumerate() {
        let is_first = i == 0;
        let pipe_open = i != 0; // not first = pipe_open
        items.push(Item {
            name: file.display_name(args.full_paths),
            size: file.size,
            depth: 1,
            is_dir: file.is_dir,
            is_first_child: is_first,
            has_shown_children: false,
            anc_pipe_open: vec![pipe_open],
            anc1_size: file.size,
            anc2_size: file.size,
            anc3_size: file.size,
            ftime_secs: None,
            skip_total_mode: false,
        });
    }

    // Add root
    if nodes.len() == 1 {
        items.push(Item {
            name: nodes[0].display_name(args.full_paths),
            size: root_size,
            depth: 0,
            is_dir: true,
            is_first_child: true,
            has_shown_children: n > 0,
            anc_pipe_open: vec![],
            anc1_size: root_size,
            anc2_size: root_size,
            anc3_size: root_size,
            ftime_secs: None,
            skip_total_mode: false,
        });
    } else {
        items.push(Item {
            name: "(total)".to_string(),
            size: root_size,
            depth: 0,
            is_dir: true,
            is_first_child: true,
            has_shown_children: n > 0,
            anc_pipe_open: vec![],
            anc1_size: root_size,
            anc2_size: root_size,
            anc3_size: root_size,
            ftime_secs: None,
            skip_total_mode: false,
        });
    }

    if args.reverse {
        items.reverse();
        // Fix is_first_child for reversed
        for item in items.iter_mut() {
            if item.depth == 0 { item.is_first_child = true; continue; }
        }
        // In reversed mode, is_first_child = (smallest) = True for last item in forward sort
        // After reversing: the last item was the largest (not first in ascending) 
        // For reversed display: last item = smallest = uses └
        let m = items.len();
        for i in 0..m {
            if items[i].depth == 1 {
                // is_first in reversed = it's the smallest = originally was is_first in forward
                // After reversing the list, items that were last (largest) are now first in display
                // The LAST item in reversed display (smallest) should use └ = is_first_child=true
                // So: is_first_child = True only for the LAST item at depth=1 in reversed list
                let last_depth1 = items[i..].iter().rposition(|it| it.depth == 1).map(|j| i+j).unwrap_or(i);
                items[i].is_first_child = i == last_depth1;

                // anc_pipe_open: in reversed, pipe_open = NOT smallest = True for first shown
                // = True for all EXCEPT the last shown (smallest)
                if i == last_depth1 {
                    items[i].anc_pipe_open = vec![false]; // last = no more after
                } else {
                    items[i].anc_pipe_open = vec![true];  // more items after
                }
            }
        }
    }

    // Use existing print logic
    let size_col = items.iter().map(|i| format_size(i.size, args).len()).max().unwrap_or(4);
    let name_col = items.iter().map(|item| {
        let prefix = build_prefix(item, args.reverse);
        prefix.chars().count() + item.name.chars().count()
    }).max().unwrap_or(10);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    if args.no_percent_bars {
        for item in &items {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let line = format!("{:>width$}{}{}", sz, prefix, item.name, width = size_col);
            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    } else {
        let pct_width = 5;
        let overhead = size_col + name_col + 1 + 1 + pct_width;
        let bar_width = if term_width > overhead { term_width - overhead } else { 0 };

        for item in &items {
            let sz = format_size(item.size, args);
            let prefix = build_prefix(item, args.reverse);
            let pct = if root_size > 0 {
                (item.size as f64 / root_size as f64 * 100.0).round() as u64
            } else { 0 };
            let bar = if args.bars_on_right {
                build_bar_right(item, root_size, bar_width)
            } else {
                build_bar(item, root_size, bar_width)
            };

            let name_part = format!("{}{}", prefix, item.name);
            let name_part_len = name_part.chars().count();
            let padding = if name_part_len < name_col { name_col - name_part_len } else { 0 };

            let line = format!("{:>width$}{}{}│{}│{:>4}%",
                sz, name_part, " ".repeat(padding),
                bar, pct, width = size_col);

            if use_color {
                writeln!(out, "{}{}{}", get_color(item.depth), line, RESET).ok();
            } else {
                writeln!(out, "{}", line).ok();
            }
        }
    }
}

