/// Apply regex filters and recalculate sizes.
/// Returns the recalculated size of this node after filtering,
/// and modifies children sizes accordingly.
pub fn apply_filter(node: &mut Node, args: &crate::args::Args) -> u64 {
    let path_str = node.path.to_string_lossy().into_owned();

    // For files: check if they match filter criteria
    if !node.is_dir {
        // Apply include filter
        if !args.filter.is_empty() {
            let matches = args.filter.iter().any(|f| crate::filter::regex_matches(f, &path_str));
            if !matches { return 0; }
        }
        // Apply invert filter (exclude)
        if !args.invert_filter.is_empty() {
            let excluded = args.invert_filter.iter().any(|f| crate::filter::regex_matches(f, &path_str));
            if excluded { return 0; }
        }
        if !args.extra_invert_filters.is_empty() {
            let excluded = args.extra_invert_filters.iter().any(|f| crate::filter::regex_matches(f, &path_str));
            if excluded { return 0; }
        }
        return node.size;
    }

    // For directories: recurse and recalculate
    // Apply filters to children
    let mut total_child_size = 0u64;
    for child in node.children.iter_mut() {
        let child_size = apply_filter(child, args);
        child.size = child_size;
        total_child_size += child_size;
    }

    // Remove children with zero size (unless they had no filter applied)
    // Actually keep zero-size items too (they might be empty dirs)

    // Directory's own size = sum of filtered children + own blocks
    // But for directories, the "own blocks" are typically 0 in my implementation
    // (I add own_size + children.sum). So just use total_child_size.
    // However, for the root directory, we don't want to lose the directory's own blocks.
    // 
    // For simplicity: keep the directory structure, just recalculate size as total_child_size
    // If directory has no children after filtering, still show it with 0 size? 
    // Or remove it?
    // Based on expected behavior: directories with no matching content are NOT shown.
    // But empty directories ARE shown (they have no children regardless of filter).

    if node.children.is_empty() {
        // Empty directory: check if we should show it
        // With filter: if path matches filter include it, else check if it's an empty dir
        if !args.filter.is_empty() {
            let matches = args.filter.iter().any(|f| crate::filter::regex_matches(f, &path_str));
            // Empty dirs with filter: might want to show them if they match or not
            // Based on expected behavior: empty dirs are shown with 0B
            // For simplicity, keep empty dirs regardless of filter
        }
        return node.size; // Keep original size (0B for empty dirs)
    }

    // Non-empty directory: recalculate size
    // Keep own block size plus filtered children
    // The original size was: own_blocks + sum(children)
    // After filter: keep own_blocks + sum(filtered_children)
    let own_blocks = if args.apparent_size {
        0 // apparent size: own size is already counted in own blocks
    } else {
        // The original size included own blocks + children
        // We can't easily extract own blocks here
        // For simplicity: use only children sizes
        0u64
    };

    let new_size = own_blocks + total_child_size;
    new_size
}
